---
// fir Optimizer — P3.3 Constant Folding
// 컴파일 타임에 평가 가능한 표현식을 상수로 대체
//
// 구현 방식: value substitution map
//   1. 각 instruction이 상수로 폴딩 가능한지 판단
//   2. 폴딩 가능하면 env[%result] = ConstValue 기록 후 instruction 제거
//   3. 모든 operand는 env 테이블을 거쳐 상수 치환됨
//   4. 수렴할 때까지 반복 (보통 1-2회)
//
// 이 방식은 "add const, 0" 형태를 만들지 않으므로 무한루프 없음
package opt

import (
	"math"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// ConstFoldPass
// ----------------------------------------------------------------

type ConstFoldPass struct{}

func (p *ConstFoldPass) Name() string { return "constfold" }

func (p *ConstFoldPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		foldFunc(fn)
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 폴딩 (반복 수렴)
// ----------------------------------------------------------------

func foldFunc(fn *ir.Function) {
	// 수렴할 때까지 반복 (한 번에 다 안 될 수 있음)
	for {
		changed := false
		// env: %reg → 상수 Value (블록 경계 무시 — SSA 불변)
		env := map[string]*ir.Value{}
		for _, b := range fn.Blocks {
			if foldBlock(b, env) {
				changed = true
			}
		}
		if !changed {
			break
		}
	}
}

// ----------------------------------------------------------------
// 블록 단위 폴딩
// ----------------------------------------------------------------

func foldBlock(b *ir.Block, env map[string]*ir.Value) bool {
	changed := false
	newInsts := make([]*ir.Inst, 0, len(b.Insts))

	for _, inst := range b.Insts {
		// 1) operand를 env로 치환 (in-place)
		subst(inst, env)

		// 2) 폴딩 시도
		if cv := tryFold(inst); cv != nil {
			// %result → 상수 기록, instruction 제거
			if inst.Result != "" {
				env[inst.Result] = cv
			}
			changed = true
			// brcond → br 변환은 instruction을 남겨야 함
			// tryFold가 nil 반환 = 제거, *Value 반환 = 상수로 기록 후 제거
			// 단, brcond 같은 terminator는 별도 처리
		} else if brInst := tryFoldBrCond(inst); brInst != nil {
			newInsts = append(newInsts, brInst)
			changed = true
		} else {
			newInsts = append(newInsts, inst)
		}
	}

	b.Insts = newInsts
	return changed
}

// ----------------------------------------------------------------
// Operand 치환: env에 있는 %reg → 상수로
// ----------------------------------------------------------------

func subst(inst *ir.Inst, env map[string]*ir.Value) {
	substVal := func(v *ir.Value) *ir.Value {
		if v == nil { return nil }
		if v.Kind == ir.ValReg {
			if cv, ok := env[v.Name]; ok {
				return cv
			}
		}
		return v
	}

	switch inst.Kind {
	case ir.InstBinop, ir.InstICmp, ir.InstFCmp:
		inst.LHS = substVal(inst.LHS)
		inst.RHS = substVal(inst.RHS)
	case ir.InstNeg, ir.InstCast:
		inst.Operand = substVal(inst.Operand)
	case ir.InstStore:
		inst.Val = substVal(inst.Val)
		inst.Ptr = substVal(inst.Ptr)
	case ir.InstLoad:
		inst.Ptr = substVal(inst.Ptr)
	case ir.InstGEP:
		inst.Ptr = substVal(inst.Ptr)
		inst.Idx = substVal(inst.Idx)
	case ir.InstCall:
		for i, a := range inst.Args {
			inst.Args[i] = substVal(a)
		}
	case ir.InstBrCond:
		inst.Cond = substVal(inst.Cond)
	case ir.InstRet:
		inst.Val = substVal(inst.Val)
	case ir.InstPhi:
		for i := range inst.Incoming {
			inst.Incoming[i].Val = substVal(inst.Incoming[i].Val)
		}
	}
}

// ----------------------------------------------------------------
// 개별 instruction 폴딩 시도
// 반환: 상수 Value (instruction 제거됨), nil이면 폴딩 불가
// ----------------------------------------------------------------

func tryFold(inst *ir.Inst) *ir.Value {
	switch inst.Kind {
	case ir.InstBinop:
		return foldBinop(inst)
	case ir.InstICmp:
		return foldICmp(inst)
	case ir.InstFCmp:
		return foldFCmp(inst)
	case ir.InstCast:
		return foldCast(inst)
	case ir.InstNeg:
		if isConstInt(inst.Operand) {
			return ir.ConstInt(-inst.Operand.IVal, inst.Type)
		}
	}
	return nil
}

// brcond 전용: constant branch → unconditional br 변환
// 반환: 새 Br instruction, nil이면 변환 불가
func tryFoldBrCond(inst *ir.Inst) *ir.Inst {
	if inst.Kind != ir.InstBrCond { return nil }
	cond := inst.Cond
	if cond == nil { return nil }
	switch cond.Kind {
	case ir.ValConstBool:
		if cond.BVal { return ir.NewBr(inst.TrueLabel) }
		return ir.NewBr(inst.FalseLabel)
	case ir.ValConstInt:
		if cond.IVal != 0 { return ir.NewBr(inst.TrueLabel) }
		return ir.NewBr(inst.FalseLabel)
	}
	return nil
}

// ----------------------------------------------------------------
// Binop 폴딩
// ----------------------------------------------------------------

func foldBinop(inst *ir.Inst) *ir.Value {
	lhs, rhs := inst.LHS, inst.RHS

	// 양쪽 모두 상수 — 직접 계산
	if isConstInt(lhs) && isConstInt(rhs) {
		v := evalIntBinop(inst.Op, lhs.IVal, rhs.IVal)
		return ir.ConstInt(v, inst.Type)
	}
	if isConstFloat(lhs) && isConstFloat(rhs) {
		v := evalFloatBinop(inst.Op, lhs.FVal, rhs.FVal)
		return ir.ConstFloat(v, inst.Type)
	}

	// 정수 한쪽 상수 — identity / zero rule
	// 반환은 상수 Value (레지스터가 아닌 값으로 치환)
	// identity 규칙은 %result → 상수가 아닌 레지스터 Value로 치환
	// 이 경우도 env에 저장되어 use-site에서 치환됨
	if !isConstFloat(lhs) && !isConstFloat(rhs) {
		switch inst.Op {
		case "add":
			if isZeroInt(rhs) { return regOrConst(lhs) }
			if isZeroInt(lhs) { return regOrConst(rhs) }
		case "sub":
			if isZeroInt(rhs) { return regOrConst(lhs) }
			if sameReg(lhs, rhs) { return ir.ConstInt(0, inst.Type) }
		case "mul":
			if isZeroInt(lhs) || isZeroInt(rhs) {
				return ir.ConstInt(0, inst.Type)
			}
			if isOneInt(rhs) { return regOrConst(lhs) }
			if isOneInt(lhs) { return regOrConst(rhs) }
		case "div":
			if isOneInt(rhs)  { return regOrConst(lhs) }
			if isZeroInt(lhs) { return ir.ConstInt(0, inst.Type) }
		case "and":
			if isZeroInt(lhs) || isZeroInt(rhs) {
				return ir.ConstInt(0, inst.Type)
			}
		case "or":
			if isZeroInt(rhs) { return regOrConst(lhs) }
			if isZeroInt(lhs) { return regOrConst(rhs) }
		case "xor":
			if sameReg(lhs, rhs) { return ir.ConstInt(0, inst.Type) }
			if isZeroInt(rhs)    { return regOrConst(lhs) }
		case "shl", "shr":
			if isZeroInt(rhs) { return regOrConst(lhs) }
			if isZeroInt(lhs) { return ir.ConstInt(0, inst.Type) }
		}
	}
	return nil
}

// regOrConst: Value를 그대로 반환 (레지스터 포함)
// env[result] = regOrConst(src) → use-site에서 src로 치환됨
func regOrConst(v *ir.Value) *ir.Value { return v }

func evalIntBinop(op string, l, r int64) int64 {
	switch op {
	case "add": return l + r
	case "sub": return l - r
	case "mul": return l * r
	case "div": if r != 0 { return l / r }; return 0
	case "rem": if r != 0 { return l % r }; return 0
	case "and": return l & r
	case "or":  return l | r
	case "xor": return l ^ r
	case "shl": return l << uint(r)
	case "shr": return l >> uint(r)
	}
	return 0
}

func evalFloatBinop(op string, l, r float64) float64 {
	switch op {
	case "fadd": return l + r
	case "fsub": return l - r
	case "fmul": return l * r
	case "fdiv": if r != 0 { return l / r }; return math.NaN()
	}
	return 0
}

// ----------------------------------------------------------------
// ICmp 폴딩
// ----------------------------------------------------------------

func foldICmp(inst *ir.Inst) *ir.Value {
	lhs, rhs := inst.LHS, inst.RHS

	// 같은 레지스터 비교
	if sameReg(lhs, rhs) {
		var result int64
		switch inst.Pred {
		case "eq", "le", "ge": result = 1
		default:               result = 0
		}
		return ir.ConstInt(result, ir.Bool())
	}

	// 양쪽 상수
	if isConstInt(lhs) && isConstInt(rhs) {
		var cmp bool
		l, r := lhs.IVal, rhs.IVal
		switch inst.Pred {
		case "eq":  cmp = l == r
		case "ne":  cmp = l != r
		case "lt":  cmp = l < r
		case "le":  cmp = l <= r
		case "gt":  cmp = l > r
		case "ge":  cmp = l >= r
		case "ult": cmp = uint64(l) < uint64(r)
		case "ule": cmp = uint64(l) <= uint64(r)
		case "ugt": cmp = uint64(l) > uint64(r)
		case "uge": cmp = uint64(l) >= uint64(r)
		}
		v := int64(0)
		if cmp { v = 1 }
		return ir.ConstInt(v, ir.Bool())
	}
	return nil
}

// ----------------------------------------------------------------
// FCmp 폴딩
// ----------------------------------------------------------------

func foldFCmp(inst *ir.Inst) *ir.Value {
	lhs, rhs := inst.LHS, inst.RHS
	if isConstFloat(lhs) && isConstFloat(rhs) {
		var cmp bool
		l, r := lhs.FVal, rhs.FVal
		switch inst.Pred {
		case "oeq": cmp = l == r
		case "one": cmp = l != r
		case "olt": cmp = l < r
		case "ole": cmp = l <= r
		case "ogt": cmp = l > r
		case "oge": cmp = l >= r
		}
		v := int64(0)
		if cmp { v = 1 }
		return ir.ConstInt(v, ir.Bool())
	}
	return nil
}

// ----------------------------------------------------------------
// Cast 폴딩
// ----------------------------------------------------------------

func foldCast(inst *ir.Inst) *ir.Value {
	v := inst.Operand
	if !isConstInt(v) && !isConstFloat(v) { return nil }

	switch inst.Op {
	case "trunc":
		if isConstInt(v) {
			iv := v.IVal
			switch inst.ToType.Name {
			case "i8",  "u8":  iv &= 0xFF
			case "i16", "u16": iv &= 0xFFFF
			case "i32", "u32": iv &= 0xFFFFFFFF
			}
			return ir.ConstInt(iv, inst.ToType)
		}
	case "zext", "sext":
		if isConstInt(v) {
			return ir.ConstInt(v.IVal, inst.ToType)
		}
	case "sitofp":
		if isConstInt(v) {
			return ir.ConstFloat(float64(v.IVal), inst.ToType)
		}
	case "fptosi":
		if isConstFloat(v) {
			return ir.ConstInt(int64(v.FVal), inst.ToType)
		}
	case "bitcast", "ptrtoint", "inttoptr":
		if isConstInt(v) {
			return ir.ConstInt(v.IVal, inst.ToType)
		}
	}
	return nil
}

// ----------------------------------------------------------------
// 헬퍼
// ----------------------------------------------------------------

func isConstInt(v *ir.Value) bool {
	return v != nil && v.Kind == ir.ValConstInt
}

func isConstFloat(v *ir.Value) bool {
	return v != nil && v.Kind == ir.ValConstFloat
}

func isZeroInt(v *ir.Value) bool {
	return isConstInt(v) && v.IVal == 0
}

func isOneInt(v *ir.Value) bool {
	return isConstInt(v) && v.IVal == 1
}

func sameReg(a, b *ir.Value) bool {
	return a != nil && b != nil &&
		a.Kind == ir.ValReg && b.Kind == ir.ValReg &&
		a.Name == b.Name
}

