   432→	for _, e := range m.Externs { sb.WriteString(e.String() + "\n") }
   433→	if len(m.Externs) > 0 { sb.WriteString("\n") }
   434→	for _, g := range m.Globals {
   435→		sb.WriteString(fmt.Sprintf("global @%s: %s\n", g.Name, g.Type))
   436→	}
   437→	if len(m.Globals) > 0 { sb.WriteString("\n") }
   438→	for _, f := range m.Functions { sb.WriteString(f.String() + "\n\n") }
   439→	return sb.String()
