// fir Optimizer — Dead Block Elimination
// brcond가 br로 폴딩된 뒤 도달 불가 블록을 제거한다.
//
// 알고리즘:
//   1. entry(첫 블록)에서 BFS — 각 블록의 terminator가 가리키는 블록만 추가
//   2. 방문하지 않은 블록 제거
//   3. 살아남은 블록의 phi incoming에서 죽은 블록 참조 정리
//      (phi incoming이 0개가 되면 phi 자체도 제거)
package opt

import "fir/src/ir"

// ----------------------------------------------------------------
// DeadBlockPass
// ----------------------------------------------------------------

type DeadBlockPass struct{}

func (p *DeadBlockPass) Name() string { return "deadblock" }

func (p *DeadBlockPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		elimDeadBlocks(fn)
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 dead block 제거
// ----------------------------------------------------------------

func elimDeadBlocks(fn *ir.Function) {
	if len(fn.Blocks) == 0 {
		return
	}

	// 1. BFS로 도달 가능한 블록 집합 계산
	reachable := make(map[string]bool)
	queue := []string{fn.Blocks[0].Label}
	reachable[fn.Blocks[0].Label] = true

	// label → Block 맵
	blockMap := make(map[string]*ir.Block)
	for _, b := range fn.Blocks {
		blockMap[b.Label] = b
	}

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		b, ok := blockMap[cur]
		if !ok {
			continue
		}
		for _, succ := range successors(b) {
			if !reachable[succ] {
				reachable[succ] = true
				queue = append(queue, succ)
			}
		}
	}

	// 2. 도달 불가 블록 제거
	kept := fn.Blocks[:0]
	for _, b := range fn.Blocks {
		if reachable[b.Label] {
			kept = append(kept, b)
		}
	}
	fn.Blocks = kept

	// 3. phi incoming에서 죽은 블록 참조 정리
	for _, b := range fn.Blocks {
		cleanPhis(b, reachable)
	}
}

// 블록의 terminator에서 후계 블록 label 목록 반환
func successors(b *ir.Block) []string {
	if len(b.Insts) == 0 {
		return nil
	}
	last := b.Insts[len(b.Insts)-1]
	switch last.Kind {
	case ir.InstBr:
		return []string{last.Target}
	case ir.InstBrCond:
		return []string{last.TrueLabel, last.FalseLabel}
	}
	return nil
}

// phi incoming에서 죽은 블록 참조 제거
// incoming이 0개가 된 phi는 instruction 자체를 제거
func cleanPhis(b *ir.Block, reachable map[string]bool) {
	newInsts := b.Insts[:0]
	for _, inst := range b.Insts {
		if inst.Kind != ir.InstPhi {
			newInsts = append(newInsts, inst)
			continue
		}
		// 살아있는 블록에서 오는 incoming만 유지
		live := inst.Incoming[:0]
		for _, inc := range inst.Incoming {
			if reachable[inc.Block] {
				live = append(live, inc)
			}
		}
		inst.Incoming = live
		// incoming이 남아 있으면 유지, 없으면 phi 제거
		if len(live) > 0 {
			newInsts = append(newInsts, inst)
		}
	}
	b.Insts = newInsts
}

