func (c *fnCtx) startBlock(label string) {
	if !c.cur.IsTerminated() {
		// 암묵적 br (fallthrough)
		c.emit(ir.NewBr(label))
	}
	c.fn.AddBlock(c.cur)
	c.cur = ir.NewBlock(label)
}

// 현재 블록 강제 마무리
func (c *fnCtx) finishBlock() {
	c.fn.AddBlock(c.cur)
}

// ----------------------------------------------------------------
// 연산자 → IR op 매핑
// ----------------------------------------------------------------

func binopToIROp(op string, isFloat bool) string {
	if isFloat {
		switch op {
		case "+": return "fadd"
		case "-": return "fsub"
		case "*": return "fmul"
		case "/": return "fdiv"
		}
	}
	switch op {
	case "+": return "add"
	case "-": return "sub"
	case "*": return "mul"
	case "/": return "div"
	case "%": return "rem"
	case "&": return "and"
	case "|": return "or"
	case "^": return "xor"
	case "<<": return "shl"
	case ">>": return "shr"
	}
	return op
}

func cmpToIRPred(op string, isFloat bool) (string, bool) {
	if isFloat {
		switch op {
		case "==": return "oeq", true
		case "!=": return "one", true
		case "<":  return "olt", true
		case "<=": return "ole", true
		case ">":  return "ogt", true
		case ">=": return "oge", true
		}
	}
	switch op {
	case "==": return "eq",  false
	case "!=": return "ne",  false
	case "<":  return "lt",  false
	case "<=": return "le",  false
	case ">":  return "gt",  false
	case ">=": return "ge",  false
	}
	return "eq", false
}

// ----------------------------------------------------------------
// 표현식 컴파일 → *ir.Value
// ----------------------------------------------------------------

func (c *fnCtx) compileExpr(e *Expr) (*ir.Value, error) {
	switch e.Kind {

	case ExprInt:
		return ir.ConstInt(e.IVal, ir.I64()), nil

	case ExprFloat:
		return ir.ConstFloat(e.FVal, ir.F64()), nil

	case ExprBool:
		return ir.ConstBool(e.BVal), nil

	case ExprIdent:
		lv, ok := c.locals[e.SVal]
		if !ok {
			// 파라미터 레지스터로 직접 접근 (alloca 없이)
			return ir.Reg(e.SVal, ir.I64()), nil
		}
		res := c.newReg("v")
		c.emit(ir.NewLoad(res, lv.irType, ir.Reg(lv.ptrReg, ir.Ptr(lv.irType))))
		return ir.Reg(res, lv.irType), nil

	case ExprBinop:
		// 비교 연산자
		switch e.Op {
		case "==", "!=", "<", "<=", ">", ">=":
			lv, err := c.compileExpr(e.Left)
			if err != nil { return nil, err }
			rv, err := c.compileExpr(e.Right)
			if err != nil { return nil, err }
			isFloat := lv.Type != nil && (lv.Type.Kind == ir.TyF32 || lv.Type.Kind == ir.TyF64)
			pred, useF := cmpToIRPred(e.Op, isFloat)
			res := c.newReg("c")
			if useF {
				c.emit(ir.NewFCmp(pred, res, ir.F64(), lv, rv))
			} else {
				c.emit(ir.NewICmp(pred, res, lv.Type, lv, rv))
			}
			return ir.Reg(res, ir.Bool()), nil

		case "&&":
			// short-circuit: 스택 변수로 처리
			res := c.newReg("and")
			ptrName := res + "_ptr"
			c.emit(ir.NewAlloca(ptrName, ir.Bool()))
			c.emit(ir.NewStore(ir.Bool(), ir.ConstBool(false), ir.Reg(ptrName, ir.Ptr(ir.Bool()))))

			lblCheck := c.newLabel("and_check")
			lblEnd   := c.newLabel("and_end")

			lv, err := c.compileExpr(e.Left)
			if err != nil { return nil, err }
			c.emit(ir.NewBrCond(lv, lblCheck, lblEnd))
			c.startBlock(lblCheck)
			rv, err := c.compileExpr(e.Right)
			if err != nil { return nil, err }
			c.emit(ir.NewStore(ir.Bool(), rv, ir.Reg(ptrName, ir.Ptr(ir.Bool()))))
			c.startBlock(lblEnd)
			loaded := c.newReg("r")
			c.emit(ir.NewLoad(loaded, ir.Bool(), ir.Reg(ptrName, ir.Ptr(ir.Bool()))))
			return ir.Reg(loaded, ir.Bool()), nil

		case "||":
			res := c.newReg("or")
			ptrName := res + "_ptr"
			c.emit(ir.NewAlloca(ptrName, ir.Bool()))
			c.emit(ir.NewStore(ir.Bool(), ir.ConstBool(true), ir.Reg(ptrName, ir.Ptr(ir.Bool()))))

			lblCheck := c.newLabel("or_check")
			lblEnd   := c.newLabel("or_end")

			lv, err := c.compileExpr(e.Left)
			if err != nil { return nil, err }
			c.emit(ir.NewBrCond(lv, lblEnd, lblCheck))
			c.startBlock(lblCheck)
			rv, err := c.compileExpr(e.Right)
			if err != nil { return nil, err }
			c.emit(ir.NewStore(ir.Bool(), rv, ir.Reg(ptrName, ir.Ptr(ir.Bool()))))
			c.startBlock(lblEnd)
			loaded := c.newReg("r")
			c.emit(ir.NewLoad(loaded, ir.Bool(), ir.Reg(ptrName, ir.Ptr(ir.Bool()))))
			return ir.Reg(loaded, ir.Bool()), nil

