// ----------------------------------------------------------------
// 문장 컴파일
// ----------------------------------------------------------------

func (c *fnCtx) compileStmt(s *Stmt) error {
	switch s.Kind {

	case StmtLet:
		irType := ir.I64()
		if s.VarType != nil { irType = astTypeToIR(s.VarType) }

		// alloca
		ptrName := s.VarName + "_ptr"
		c.emit(ir.NewAlloca(ptrName, irType))
		c.locals[s.VarName] = localVar{ptrReg: ptrName, irType: irType}

		// 초기화
		if s.Init != nil {
			val, err := c.compileExpr(s.Init)
			if err != nil { return err }
			c.emit(ir.NewStore(irType, val, ir.Reg(ptrName, ir.Ptr(irType))))
		}
		return nil

	case StmtAssign:
		lv, ok := c.locals[s.Target]
		if !ok {
			return fmt.Errorf("undefined variable: %s", s.Target)
		}
		val, err := c.compileExpr(s.Value)
		if err != nil { return err }
		c.emit(ir.NewStore(lv.irType, val, ir.Reg(lv.ptrReg, ir.Ptr(lv.irType))))
		return nil

	case StmtReturn:
		if s.RetVal == nil || c.retType.Kind == ir.TyVoid {
			c.emit(ir.NewRetVoid())
		} else {
			val, err := c.compileExpr(s.RetVal)
			if err != nil { return err }
			c.emit(ir.NewRet(val))
		}
		return nil

	case StmtIf:
		lblThen := c.newLabel("if_then")
		lblElse := c.newLabel("if_else")
		lblEnd  := c.newLabel("if_end")

		cond, err := c.compileExpr(s.Cond)
		if err != nil { return err }

		if len(s.Else) > 0 {
			c.emit(ir.NewBrCond(cond, lblThen, lblElse))
		} else {
			c.emit(ir.NewBrCond(cond, lblThen, lblEnd))
		}

		// then
		c.startBlock(lblThen)
		for _, st := range s.Then {
			if err := c.compileStmt(st); err != nil { return err }
		}
		if !c.cur.IsTerminated() {
			c.emit(ir.NewBr(lblEnd))
		}

		// else
		if len(s.Else) > 0 {
			c.startBlock(lblElse)
			for _, st := range s.Else {
				if err := c.compileStmt(st); err != nil { return err }
			}
			if !c.cur.IsTerminated() {
				c.emit(ir.NewBr(lblEnd))
			}
		}

		c.startBlock(lblEnd)
		return nil

	case StmtWhile:
		lblCond := c.newLabel("while_cond")
		lblBody := c.newLabel("while_body")
		lblEnd  := c.newLabel("while_end")

		c.emit(ir.NewBr(lblCond))
		c.startBlock(lblCond)

		cond, err := c.compileExpr(s.Cond)
		if err != nil { return err }
		c.emit(ir.NewBrCond(cond, lblBody, lblEnd))

		c.startBlock(lblBody)
		for _, st := range s.Body {
			if err := c.compileStmt(st); err != nil { return err }
		}
		if !c.cur.IsTerminated() {
			c.emit(ir.NewBr(lblCond))
		}

		c.startBlock(lblEnd)
		return nil

	case StmtExpr:
		_, err := c.compileExpr(s.ExprVal)
		return err
	}

	return nil
}

// ----------------------------------------------------------------
// 함수 컴파일
// ----------------------------------------------------------------

func compileFn(mod *ir.Module, decl *FnDecl,
	externSigs map[string]*ir.Type, fnSigs map[string]*fnSig) error {

	retType := astTypeToIR(decl.RetType)
	params := make([]ir.Param, len(decl.Params))
	for i, p := range decl.Params {
		params[i] = ir.Param{Name: p.Name, Type: astTypeToIR(p.Type)}
	}

	fn := ir.NewFunction(decl.Name, params, retType, false)
	ctx := newFnCtx(mod, fn, retType, externSigs, fnSigs)

	// 파라미터를 alloca+store로 내림 (SSA 단순화)
	for _, p := range decl.Params {
		irT := astTypeToIR(p.Type)
		ptrName := p.Name + "_ptr"
		ctx.emit(ir.NewAlloca(ptrName, irT))
		ctx.emit(ir.NewStore(irT, ir.Reg(p.Name, irT), ir.Reg(ptrName, ir.Ptr(irT))))
		ctx.locals[p.Name] = localVar{ptrReg: ptrName, irType: irT}
	}

	for _, s := range decl.Body {
		if err := ctx.compileStmt(s); err != nil { return err }
	}

	// 함수 끝에 암묵적 ret void
	if !ctx.cur.IsTerminated() {
		if retType.Kind == ir.TyVoid {
			ctx.emit(ir.NewRetVoid())
		} else {
			ctx.emit(ir.NewRet(ir.ConstInt(0, retType)))
		}
	}
	ctx.finishBlock()
	mod.AddFunction(fn)
	return nil
}

// ----------------------------------------------------------------
// 모듈 컴파일 (진입점)
// ----------------------------------------------------------------

func Compile(src string) (*ir.Module, error) {
	prog, err := ParseProgram(src)
	if err != nil { return nil, fmt.Errorf("parse: %w", err) }
	return CompileProgram(prog)
}

func CompileProgram(prog *Program) (*ir.Module, error) {
	mod := ir.NewModule("fl")

	// 1패스: 시그니처 수집
	externSigs := make(map[string]*ir.Type)
	fnSigs     := make(map[string]*fnSig)

	for _, decl := range prog.Fns {
		retT := astTypeToIR(decl.RetType)
		paramTs := make([]*ir.Type, len(decl.Params))
		for i, p := range decl.Params { paramTs[i] = astTypeToIR(p.Type) }

		if decl.IsExtern {
			externSigs[decl.Name] = retT
			ext := &ir.ExternFunction{
				Name: decl.Name, ParamTypes: paramTs, RetType: retT,
			}
			mod.AddExtern(ext)
		} else {
			fnSigs[decl.Name] = &fnSig{params: paramTs, retType: retT}
		}
	}

	// 2패스: 함수 바디 컴파일
	for _, decl := range prog.Fns {
		if decl.IsExtern { continue }
		if err := compileFn(mod, decl, externSigs, fnSigs); err != nil {
			return nil, fmt.Errorf("fn %s: %w", decl.Name, err)
		}
	}

	return mod, nil
}

