// fir Optimizer — P3.1 mem2reg (alloca → SSA phi)
//
// 알고리즘: Cytron et al. (1991) SSA 변환 — 교과서 표준 구현
//
//   1. promotable alloca 탐지
//      조건: ptr이 load/store에만 쓰이고 address-taken 아님
//
//   2. CFG 구성 (predecessors)
//
//   3. Dominance 계산 (iterative dataflow — 역후위순서)
//
//   4. Dominance Frontier 계산
//
//   5. phi 삽입
//      - 각 alloca 변수의 store 위치에서 DF 계산
//      - frontier 블록에 phi 노드 삽입
//      - phi 삽입이 새 DF를 만들 수 있으므로 수렴까지 반복
//
//   6. rename 패스 (DFS, dominator tree 순서)
//      - alloca 제거
//      - store → 현재 def 갱신 (instruction 제거)
//      - load  → 현재 def 값으로 치환 (instruction 제거)
//      - phi   → incoming 값 연결
package opt

import (
	"fmt"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// Mem2RegPass
// ----------------------------------------------------------------

type Mem2RegPass struct{}

func (p *Mem2RegPass) Name() string { return "mem2reg" }

func (p *Mem2RegPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		if len(fn.Blocks) > 0 {
			mem2regFunc(fn)
		}
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 mem2reg
// ----------------------------------------------------------------

func mem2regFunc(fn *ir.Function) {
	// 1. promotable alloca 탐지
	promotable := findPromotable(fn)
	if len(promotable) == 0 {
		return
	}

	// 2. CFG: label → Block, predecessors
	blockMap := make(map[string]*ir.Block)
	for _, b := range fn.Blocks {
		blockMap[b.Label] = b
	}
	preds := buildPreds(fn, blockMap)

	// 3. Dominance 계산
	idom := computeIDom(fn, preds)

	// 4. Dominance Frontier 계산
	df := computeDF(fn, preds, idom)

	// 5. phi 삽입
	phiMap := insertPhis(fn, blockMap, df, promotable)

	// 6. rename
	rename(fn, blockMap, idom, promotable, phiMap)
}

// ----------------------------------------------------------------
// 1. Promotable alloca 탐지
// ----------------------------------------------------------------

// alloca가 승격 가능한지: load/store에만 쓰이고 address-taken 아님
func findPromotable(fn *ir.Function) map[string]bool {
	// alloca 집합 수집
	allocas := map[string]bool{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca {
				allocas[inst.Result] = true
			}
		}
	}

	// non-promotable 표시: load/store 이외 용도로 쓰이면 제외
	notPromotable := map[string]bool{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			switch inst.Kind {
			case ir.InstLoad:
				// ptr이 alloca → OK
			case ir.InstStore:
				// ptr이 alloca → OK (val은 상관없음)
				// val이 alloca 주소이면 address-taken → 제외
				if inst.Val != nil && inst.Val.Kind == ir.ValReg && allocas[inst.Val.Name] {
					notPromotable[inst.Val.Name] = true
				}
			case ir.InstAlloca:
				// alloca 자체
			default:
				// 다른 instruction에서 alloca ptr 사용 → address-taken
				for _, reg := range usedRegs(inst) {
					if allocas[reg] {
						notPromotable[reg] = true
					}
				}
			}
		}
	}

	promotable := map[string]bool{}
	for name := range allocas {
		if !notPromotable[name] {
			promotable[name] = true
		}
	}
	return promotable
}

// ----------------------------------------------------------------
// 2. CFG — predecessors
// ----------------------------------------------------------------

func buildPreds(fn *ir.Function, blockMap map[string]*ir.Block) map[string][]string {
	preds := make(map[string][]string)
	for _, b := range fn.Blocks {
		preds[b.Label] = nil // 초기화
	}
	for _, b := range fn.Blocks {
		for _, succ := range successors(b) {
			preds[succ] = append(preds[succ], b.Label)
		}
	}
	return preds
}

// ----------------------------------------------------------------
// 3. Dominance — iterative dataflow
// ----------------------------------------------------------------

// idom[b] = b의 immediate dominator label ("" = entry 또는 미확정)
func computeIDom(fn *ir.Function, preds map[string][]string) map[string]string {
	if len(fn.Blocks) == 0 {
		return nil
	}

	// 역후위순서 (reverse post-order) 계산
	rpo := reversePostOrder(fn)
	rpoIndex := make(map[string]int)
	for i, label := range rpo {
		rpoIndex[label] = i
	}

	entry := fn.Blocks[0].Label
	idom := make(map[string]string)
	idom[entry] = entry // entry dominates itself

	// Cooper et al. 단순 iterative dominator 알고리즘
	changed := true
	for changed {
		changed = false
		for _, label := range rpo {
			if label == entry {
				continue
			}
			// 처리된 predecessor 중 첫 번째
			newIdom := ""
			for _, p := range preds[label] {
				if idom[p] == "" {
					continue
				}
				if newIdom == "" {
					newIdom = p
					continue
				}
				// intersect(newIdom, p)
				newIdom = intersect(newIdom, p, idom, rpoIndex)
			}
			if newIdom == "" {
				newIdom = entry
			}
			if idom[label] != newIdom {
				idom[label] = newIdom
				changed = true
			}
		}
	}
	return idom
}

func intersect(b1, b2 string, idom map[string]string, rpoIndex map[string]int) string {
	finger1, finger2 := b1, b2
	for finger1 != finger2 {
		for rpoIndex[finger1] > rpoIndex[finger2] {
			finger1 = idom[finger1]
		}
		for rpoIndex[finger2] > rpoIndex[finger1] {
			finger2 = idom[finger2]
		}
	}
	return finger1
}

// DFS 기반 역후위순서
func reversePostOrder(fn *ir.Function) []string {
	if len(fn.Blocks) == 0 {
		return nil
	}
	blockMap := make(map[string]*ir.Block)
	for _, b := range fn.Blocks {
		blockMap[b.Label] = b
	}

	visited := map[string]bool{}
	postOrder := []string{}

	var dfs func(label string)
	dfs = func(label string) {
		if visited[label] {
			return
		}
		visited[label] = true
		b, ok := blockMap[label]
		if !ok {
			return
		}
		for _, succ := range successors(b) {
			dfs(succ)
		}
		postOrder = append(postOrder, label)
	}
	dfs(fn.Blocks[0].Label)

	// 역순
	rpo := make([]string, len(postOrder))
	for i, label := range postOrder {
		rpo[len(postOrder)-1-i] = label
	}
	return rpo
}

// ----------------------------------------------------------------
// 4. Dominance Frontier
// ----------------------------------------------------------------

func computeDF(fn *ir.Function, preds map[string][]string, idom map[string]string) map[string][]string {
	df := make(map[string][]string)
	for _, b := range fn.Blocks {
		ps := preds[b.Label]
		if len(ps) < 2 {
			continue
		}
		// b가 join point
		for _, p := range ps {
			runner := p
			for runner != idom[b.Label] {
				// runner의 DF에 b 추가
				if !contains(df[runner], b.Label) {
					df[runner] = append(df[runner], b.Label)
				}
				next := idom[runner]
				if next == runner || next == "" {
					break
				}
				runner = next
			}
		}
	}
	return df
}

func contains(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
}

// ----------------------------------------------------------------
// 5. phi 삽입
// ----------------------------------------------------------------

// phiMap[blockLabel][allocaName] = phi instruction result name
type phiInfo struct {
	result string
	irType *ir.Type
}

func insertPhis(fn *ir.Function, blockMap map[string]*ir.Block,
	df map[string][]string, promotable map[string]bool) map[string]map[string]*phiInfo {

	// alloca 타입 수집
	allocaType := map[string]*ir.Type{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca && promotable[inst.Result] {
				allocaType[inst.Result] = inst.AllocType
			}
		}
	}

	// 각 alloca 변수의 store 위치 수집
	defsIn := map[string][]string{} // allocaName → []blockLabel
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstStore {
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					if !contains(defsIn[inst.Ptr.Name], b.Label) {
						defsIn[inst.Ptr.Name] = append(defsIn[inst.Ptr.Name], b.Label)
					}
				}
			}
		}
	}

	// phiMap[block][alloca] = phiInfo
	phiMap := map[string]map[string]*phiInfo{}
	for _, b := range fn.Blocks {
		phiMap[b.Label] = map[string]*phiInfo{}
	}

	// phi 삽입 카운터
	phiCounter := 0

	for allocaName, defBlocks := range defsIn {
		irT := allocaType[allocaName]
		if irT == nil {
			continue
		}

		worklist := make([]string, len(defBlocks))
		copy(worklist, defBlocks)
		hasPhiFor := map[string]bool{}

		for len(worklist) > 0 {
			b := worklist[0]
			worklist = worklist[1:]
			for _, frontier := range df[b] {
				if hasPhiFor[frontier] {
					continue
				}
				hasPhiFor[frontier] = true
				// phi 삽입
				result := fmt.Sprintf("phi_%s_%d", allocaName, phiCounter)
				phiCounter++
				phiMap[frontier][allocaName] = &phiInfo{result: result, irType: irT}
				// frontier도 def 블록이 됨 → worklist에 추가
				worklist = append(worklist, frontier)
			}
		}
	}

	// 실제 phi instruction을 블록 앞에 삽입 (incoming은 rename에서 채움)
	for _, b := range fn.Blocks {
		phis := phiMap[b.Label]
		if len(phis) == 0 {
			continue
		}
		var phiInsts []*ir.Inst
		for _, info := range phis {
			phiInsts = append(phiInsts, ir.NewPhi(info.result, info.irType, nil))
		}
		b.Insts = append(phiInsts, b.Insts...)
	}

	return phiMap
}

// ----------------------------------------------------------------
// 6. rename 패스
// ----------------------------------------------------------------

// stacks[allocaName] = []value (SSA 값 스택)
func rename(fn *ir.Function, blockMap map[string]*ir.Block,
	idom map[string]string, promotable map[string]bool,
	phiMap map[string]map[string]*phiInfo) {

	// dominator tree children
	domChildren := map[string][]string{}
	for _, b := range fn.Blocks {
		dom := idom[b.Label]
		if dom != "" && dom != b.Label {
			domChildren[dom] = append(domChildren[dom], b.Label)
		}
	}

	// alloca 타입
	allocaType := map[string]*ir.Type{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca && promotable[inst.Result] {
				allocaType[inst.Result] = inst.AllocType
			}
		}
	}

	stacks := map[string][]*ir.Value{}

	var renameBlock func(label string)
	renameBlock = func(label string) {
		b, ok := blockMap[label]
		if !ok {
			return
		}

		// 이 블록에서 스택에 push된 항목 수 기록 (나중에 pop)
		pushed := map[string]int{}

		newInsts := []*ir.Inst{}
		for _, inst := range b.Insts {
			switch inst.Kind {

			case ir.InstAlloca:
				if promotable[inst.Result] {
					// undef 초기값 push
					undef := ir.ConstInt(0, allocaType[inst.Result])
					stacks[inst.Result] = append(stacks[inst.Result], undef)
					pushed[inst.Result]++
					// alloca instruction 제거
					continue
				}
				newInsts = append(newInsts, inst)

			case ir.InstLoad:
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					// load → 현재 스택 top으로 치환
					allocaName := inst.Ptr.Name
					top := currentDef(stacks, allocaName)
					// 이 result를 참조하는 곳은 top으로 치환
					// rename 중이므로 직접 env 대신 phi/store에서 사용
					// load result를 top으로 바꾸는 방법: 후속 instruction에서 %result → top
					// 단순 접근: load를 남기되 result를 top의 name으로 alias
					// → stacks에 top을 push하여 load result 이름으로 접근 시 top 반환
					stacks[inst.Result] = append(stacks[inst.Result], top)
					pushed[inst.Result]++
					// load instruction 제거
					continue
				}
				newInsts = append(newInsts, inst)

			case ir.InstStore:
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					allocaName := inst.Ptr.Name
					// val의 레지스터도 rename
					val := renameValue(inst.Val, stacks)
					stacks[allocaName] = append(stacks[allocaName], val)
					pushed[allocaName]++
					// store instruction 제거
					continue
				}
				// store의 val도 rename
				inst.Val = renameValue(inst.Val, stacks)
				inst.Ptr = renameValue(inst.Ptr, stacks)
				newInsts = append(newInsts, inst)

			case ir.InstPhi:
				// phi result → 스택에 push (incoming은 나중에 채움)
				stacks[inst.Result] = append(stacks[inst.Result], ir.Reg(inst.Result, inst.Type))
				pushed[inst.Result]++
				newInsts = append(newInsts, inst)

			default:
				// 일반 instruction: operand rename
				renameInst(inst, stacks)
				if inst.Result != "" {
					stacks[inst.Result] = append(stacks[inst.Result], ir.Reg(inst.Result, inst.Type))
					pushed[inst.Result]++
				}
				newInsts = append(newInsts, inst)
			}
		}
		b.Insts = newInsts

		// successor의 phi incoming 채우기
		for _, succLabel := range successors(b) {
			succPhis := phiMap[succLabel]
			succBlock, ok := blockMap[succLabel]
			if !ok {
				continue
			}
			for allocaName, info := range succPhis {
				top := currentDef(stacks, allocaName)
				// succBlock의 phi instruction에서 이 블록의 incoming 추가
				for _, inst := range succBlock.Insts {
					if inst.Kind == ir.InstPhi && inst.Result == info.result {
						inst.Incoming = append(inst.Incoming, ir.PhiIncoming{
							Val:   top,
							Block: label,
						})
						break
					}
				}
			}
		}

		// dominator tree children 재귀 방문
		for _, child := range domChildren[label] {
			renameBlock(child)
		}

		// 이 블록에서 push한 항목 pop
		for name, count := range pushed {
			if len(stacks[name]) >= count {
				stacks[name] = stacks[name][:len(stacks[name])-count]
			}
		}
	}

	if len(fn.Blocks) > 0 {
		renameBlock(fn.Blocks[0].Label)
	}

	// phi incoming이 0개인 phi 제거 (entry 블록의 phi 등)
	for _, b := range fn.Blocks {
		cleaned := b.Insts[:0]
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstPhi && len(inst.Incoming) == 0 {
				continue
			}
			cleaned = append(cleaned, inst)
		}
		b.Insts = cleaned
	}
}

// 스택 top 반환 (없으면 undef=0)
func currentDef(stacks map[string][]*ir.Value, name string) *ir.Value {
	s := stacks[name]
	if len(s) == 0 {
		return ir.ConstInt(0, ir.I64()) // undef
	}
	return s[len(s)-1]
}

// Value의 레지스터 이름을 스택에서 rename
func renameValue(v *ir.Value, stacks map[string][]*ir.Value) *ir.Value {
	if v == nil || v.Kind != ir.ValReg {
		return v
	}
	s := stacks[v.Name]
	if len(s) == 0 {
		return v
	}
	return s[len(s)-1]
}

// instruction의 모든 operand를 rename
func renameInst(inst *ir.Inst, stacks map[string][]*ir.Value) {
	rv := func(v *ir.Value) *ir.Value { return renameValue(v, stacks) }
	switch inst.Kind {
	case ir.InstBinop, ir.InstICmp, ir.InstFCmp:
		inst.LHS = rv(inst.LHS)
		inst.RHS = rv(inst.RHS)
	case ir.InstNeg, ir.InstCast:
		inst.Operand = rv(inst.Operand)
	case ir.InstLoad:
		inst.Ptr = rv(inst.Ptr)
	case ir.InstStore:
		inst.Val = rv(inst.Val)
		inst.Ptr = rv(inst.Ptr)
	case ir.InstGEP:
		inst.Ptr = rv(inst.Ptr)
		inst.Idx = rv(inst.Idx)
	case ir.InstCall:
		for i, a := range inst.Args {
			inst.Args[i] = rv(a)
		}
	case ir.InstBrCond:
		inst.Cond = rv(inst.Cond)
	case ir.InstRet:
		inst.Val = rv(inst.Val)
	case ir.InstPhi:
		for i := range inst.Incoming {
			inst.Incoming[i].Val = rv(inst.Incoming[i].Val)
		}
	}
}

toolUseResult.content:
// fir Optimizer — P3.1 mem2reg (alloca → SSA phi)
//
// 알고리즘: Cytron et al. (1991) SSA 변환 — 교과서 표준 구현
//
//   1. promotable alloca 탐지
//      조건: ptr이 load/store에만 쓰이고 address-taken 아님
//
//   2. CFG 구성 (predecessors)
//
//   3. Dominance 계산 (iterative dataflow — 역후위순서)
//
//   4. Dominance Frontier 계산
//
//   5. phi 삽입
//      - 각 alloca 변수의 store 위치에서 DF 계산
//      - frontier 블록에 phi 노드 삽입
//      - phi 삽입이 새 DF를 만들 수 있으므로 수렴까지 반복
//
//   6. rename 패스 (DFS, dominator tree 순서)
//      - alloca 제거
//      - store → 현재 def 갱신 (instruction 제거)
//      - load  → 현재 def 값으로 치환 (instruction 제거)
//      - phi   → incoming 값 연결
package opt

import (
	"fmt"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// Mem2RegPass
// ----------------------------------------------------------------

type Mem2RegPass struct{}

func (p *Mem2RegPass) Name() string { return "mem2reg" }

func (p *Mem2RegPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		if len(fn.Blocks) > 0 {
			mem2regFunc(fn)
		}
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 mem2reg
// ----------------------------------------------------------------

func mem2regFunc(fn *ir.Function) {
	// 1. promotable alloca 탐지
	promotable := findPromotable(fn)
	if len(promotable) == 0 {
		return
	}

	// 2. CFG: label → Block, predecessors
	blockMap := make(map[string]*ir.Block)
	for _, b := range fn.Blocks {
		blockMap[b.Label] = b
	}
	preds := buildPreds(fn, blockMap)

	// 3. Dominance 계산
	idom := computeIDom(fn, preds)

	// 4. Dominance Frontier 계산
	df := computeDF(fn, preds, idom)

	// 5. phi 삽입
	phiMap := insertPhis(fn, blockMap, df, promotable)

	// 6. rename
	rename(fn, blockMap, idom, promotable, phiMap)
}

// ----------------------------------------------------------------
// 1. Promotable alloca 탐지
// ----------------------------------------------------------------

// alloca가 승격 가능한지: load/store에만 쓰이고 address-taken 아님
func findPromotable(fn *ir.Function) map[string]bool {
	// alloca 집합 수집
	allocas := map[string]bool{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca {
				allocas[inst.Result] = true
			}
		}
	}

	// non-promotable 표시: load/store 이외 용도로 쓰이면 제외
	notPromotable := map[string]bool{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			switch inst.Kind {
			case ir.InstLoad:
				// ptr이 alloca → OK
			case ir.InstStore:
				// ptr이 alloca → OK (val은 상관없음)
				// val이 alloca 주소이면 address-taken → 제외
				if inst.Val != nil && inst.Val.Kind == ir.ValReg && allocas[inst.Val.Name] {
					notPromotable[inst.Val.Name] = true
				}
			case ir.InstAlloca:
				// alloca 자체
			default:
				// 다른 instruction에서 alloca ptr 사용 → address-taken
				for _, reg := range usedRegs(inst) {
					if allocas[reg] {
						notPromotable[reg] = true
					}
				}
			}
		}
	}

	promotable := map[string]bool{}
	for name := range allocas {
		if !notPromotable[name] {
			promotable[name] = true
		}
	}
	return promotable
}

// ----------------------------------------------------------------
// 2. CFG — predecessors
// ----------------------------------------------------------------

func buildPreds(fn *ir.Function, blockMap map[string]*ir.Block) map[string][]string {
	preds := make(map[string][]string)
	for _, b := range fn.Blocks {
		preds[b.Label] = nil // 초기화
	}
	for _, b := range fn.Blocks {
		for _, succ := range successors(b) {
			preds[succ] = append(preds[succ], b.Label)
		}
	}
	return preds
}

// ----------------------------------------------------------------
// 3. Dominance — iterative dataflow
// ----------------------------------------------------------------

// idom[b] = b의 immediate dominator label ("" = entry 또는 미확정)
func computeIDom(fn *ir.Function, preds map[string][]string) map[string]string {
	if len(fn.Blocks) == 0 {
		return nil
	}

	// 역후위순서 (reverse post-order) 계산
	rpo := reversePostOrder(fn)
	rpoIndex := make(map[string]int)
	for i, label := range rpo {
		rpoIndex[label] = i
	}

	entry := fn.Blocks[0].Label
	idom := make(map[string]string)
	idom[entry] = entry // entry dominates itself

	// Cooper et al. 단순 iterative dominator 알고리즘
	changed := true
	for changed {
		changed = false
		for _, label := range rpo {
			if label == entry {
				continue
			}
			// 처리된 predecessor 중 첫 번째
			newIdom := ""
			for _, p := range preds[label] {
				if idom[p] == "" {
					continue
				}
				if newIdom == "" {
					newIdom = p
					continue
				}
				// intersect(newIdom, p)
				newIdom = intersect(newIdom, p, idom, rpoIndex)
			}
			if newIdom == "" {
				newIdom = entry
			}
			if idom[label] != newIdom {
				idom[label] = newIdom
				changed = true
			}
		}
	}
	return idom
}

func intersect(b1, b2 string, idom map[string]string, rpoIndex map[string]int) string {
	finger1, finger2 := b1, b2
	for finger1 != finger2 {
		for rpoIndex[finger1] > rpoIndex[finger2] {
			finger1 = idom[finger1]
		}
		for rpoIndex[finger2] > rpoIndex[finger1] {
			finger2 = idom[finger2]
		}
	}
	return finger1
}

// DFS 기반 역후위순서
func reversePostOrder(fn *ir.Function) []string {
	if len(fn.Blocks) == 0 {
		return nil
	}
	blockMap := make(map[string]*ir.Block)
	for _, b := range fn.Blocks {
		blockMap[b.Label] = b
	}

	visited := map[string]bool{}
	postOrder := []string{}

	var dfs func(label string)
	dfs = func(label string) {
		if visited[label] {
			return
		}
		visited[label] = true
		b, ok := blockMap[label]
		if !ok {
			return
		}
		for _, succ := range successors(b) {
			dfs(succ)
		}
		postOrder = append(postOrder, label)
	}
	dfs(fn.Blocks[0].Label)

	// 역순
	rpo := make([]string, len(postOrder))
	for i, label := range postOrder {
		rpo[len(postOrder)-1-i] = label
	}
	return rpo
}

// ----------------------------------------------------------------
// 4. Dominance Frontier
// ----------------------------------------------------------------

func computeDF(fn *ir.Function, preds map[string][]string, idom map[string]string) map[string][]string {
	df := make(map[string][]string)
	for _, b := range fn.Blocks {
		ps := preds[b.Label]
		if len(ps) < 2 {
			continue
		}
		// b가 join point
		for _, p := range ps {
			runner := p
			for runner != idom[b.Label] {
				// runner의 DF에 b 추가
				if !contains(df[runner], b.Label) {
					df[runner] = append(df[runner], b.Label)
				}
				next := idom[runner]
				if next == runner || next == "" {
					break
				}
				runner = next
			}
		}
	}
	return df
}

func contains(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
}

// ----------------------------------------------------------------
// 5. phi 삽입
// ----------------------------------------------------------------

// phiMap[blockLabel][allocaName] = phi instruction result name
type phiInfo struct {
	result string
	irType *ir.Type
}

func insertPhis(fn *ir.Function, blockMap map[string]*ir.Block,
	df map[string][]string, promotable map[string]bool) map[string]map[string]*phiInfo {

	// alloca 타입 수집
	allocaType := map[string]*ir.Type{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca && promotable[inst.Result] {
				allocaType[inst.Result] = inst.AllocType
			}
		}
	}

	// 각 alloca 변수의 store 위치 수집
	defsIn := map[string][]string{} // allocaName → []blockLabel
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstStore {
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					if !contains(defsIn[inst.Ptr.Name], b.Label) {
						defsIn[inst.Ptr.Name] = append(defsIn[inst.Ptr.Name], b.Label)
					}
				}
			}
		}
	}

	// phiMap[block][alloca] = phiInfo
	phiMap := map[string]map[string]*phiInfo{}
	for _, b := range fn.Blocks {
		phiMap[b.Label] = map[string]*phiInfo{}
	}

	// phi 삽입 카운터
	phiCounter := 0

	for allocaName, defBlocks := range defsIn {
		irT := allocaType[allocaName]
		if irT == nil {
			continue
		}

		worklist := make([]string, len(defBlocks))
		copy(worklist, defBlocks)
		hasPhiFor := map[string]bool{}

		for len(worklist) > 0 {
			b := worklist[0]
			worklist = worklist[1:]
			for _, frontier := range df[b] {
				if hasPhiFor[frontier] {
					continue
				}
				hasPhiFor[frontier] = true
				// phi 삽입
				result := fmt.Sprintf("phi_%s_%d", allocaName, phiCounter)
				phiCounter++
				phiMap[frontier][allocaName] = &phiInfo{result: result, irType: irT}
				// frontier도 def 블록이 됨 → worklist에 추가
				worklist = append(worklist, frontier)
			}
		}
	}

	// 실제 phi instruction을 블록 앞에 삽입 (incoming은 rename에서 채움)
	for _, b := range fn.Blocks {
		phis := phiMap[b.Label]
		if len(phis) == 0 {
			continue
		}
		var phiInsts []*ir.Inst
		for _, info := range phis {
			phiInsts = append(phiInsts, ir.NewPhi(info.result, info.irType, nil))
		}
		b.Insts = append(phiInsts, b.Insts...)
	}

	return phiMap
}

// ----------------------------------------------------------------
// 6. rename 패스
// ----------------------------------------------------------------

// stacks[allocaName] = []value (SSA 값 스택)
func rename(fn *ir.Function, blockMap map[string]*ir.Block,
	idom map[string]string, promotable map[string]bool,
	phiMap map[string]map[string]*phiInfo) {

	// dominator tree children
	domChildren := map[string][]string{}
	for _, b := range fn.Blocks {
		dom := idom[b.Label]
		if dom != "" && dom != b.Label {
			domChildren[dom] = append(domChildren[dom], b.Label)
		}
	}

	// alloca 타입
	allocaType := map[string]*ir.Type{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca && promotable[inst.Result] {
				allocaType[inst.Result] = inst.AllocType
			}
		}
	}

	stacks := map[string][]*ir.Value{}

	var renameBlock func(label string)
	renameBlock = func(label string) {
		b, ok := blockMap[label]
		if !ok {
			return
		}

		// 이 블록에서 스택에 push된 항목 수 기록 (나중에 pop)
		pushed := map[string]int{}

		newInsts := []*ir.Inst{}
		for _, inst := range b.Insts {
			switch inst.Kind {

			case ir.InstAlloca:
				if promotable[inst.Result] {
					// undef 초기값 push
					undef := ir.ConstInt(0, allocaType[inst.Result])
					stacks[inst.Result] = append(stacks[inst.Result], undef)
					pushed[inst.Result]++
					// alloca instruction 제거
					continue
				}
				newInsts = append(newInsts, inst)

			case ir.InstLoad:
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					// load → 현재 스택 top으로 치환
					allocaName := inst.Ptr.Name
					top := currentDef(stacks, allocaName)
					// 이 result를 참조하는 곳은 top으로 치환
					// rename 중이므로 직접 env 대신 phi/store에서 사용
					// load result를 top으로 바꾸는 방법: 후속 instruction에서 %result → top
					// 단순 접근: load를 남기되 result를 top의 name으로 alias
					// → stacks에 top을 push하여 load result 이름으로 접근 시 top 반환
					stacks[inst.Result] = append(stacks[inst.Result], top)
					pushed[inst.Result]++
					// load instruction 제거
					continue
				}
				newInsts = append(newInsts, inst)

			case ir.InstStore:
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					allocaName := inst.Ptr.Name
					// val의 레지스터도 rename
					val := renameValue(inst.Val, stacks)
					stacks[allocaName] = append(stacks[allocaName], val)
					pushed[allocaName]++
					// store instruction 제거
					continue
				}
				// store의 val도 rename
				inst.Val = renameValue(inst.Val, stacks)
				inst.Ptr = renameValue(inst.Ptr, stacks)
				newInsts = append(newInsts, inst)

			case ir.InstPhi:
				// phi result → 스택에 push (incoming은 나중에 채움)
				stacks[inst.Result] = append(stacks[inst.Result], ir.Reg(inst.Result, inst.Type))
				pushed[inst.Result]++
				newInsts = append(newInsts, inst)

			default:
				// 일반 instruction: operand rename
				renameInst(inst, stacks)
				if inst.Result != "" {
					stacks[inst.Result] = append(stacks[inst.Result], ir.Reg(inst.Result, inst.Type))
					pushed[inst.Result]++
				}
				newInsts = append(newInsts, inst)
			}
		}
		b.Insts = newInsts

		// successor의 phi incoming 채우기
		for _, succLabel := range successors(b) {
			succPhis := phiMap[succLabel]
			succBlock, ok := blockMap[succLabel]
			if !ok {
				continue
			}
			for allocaName, info := range succPhis {
				top := currentDef(stacks, allocaName)
				// succBlock의 phi instruction에서 이 블록의 incoming 추가
				for _, inst := range succBlock.Insts {
					if inst.Kind == ir.InstPhi && inst.Result == info.result {
						inst.Incoming = append(inst.Incoming, ir.PhiIncoming{
							Val:   top,
							Block: label,
						})
						break
					}
				}
			}
		}

		// dominator tree children 재귀 방문
		for _, child := range domChildren[label] {
			renameBlock(child)
		}

		// 이 블록에서 push한 항목 pop
		for name, count := range pushed {
			if len(stacks[name]) >= count {
				stacks[name] = stacks[name][:len(stacks[name])-count]
			}
		}
	}

	if len(fn.Blocks) > 0 {
		renameBlock(fn.Blocks[0].Label)
	}

	// phi incoming이 0개인 phi 제거 (entry 블록의 phi 등)
	for _, b := range fn.Blocks {
		cleaned := b.Insts[:0]
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstPhi && len(inst.Incoming) == 0 {
				continue
			}
			cleaned = append(cleaned, inst)
		}
		b.Insts = cleaned
	}
}

// 스택 top 반환 (없으면 undef=0)
func currentDef(stacks map[string][]*ir.Value, name string) *ir.Value {
	s := stacks[name]
	if len(s) == 0 {
		return ir.ConstInt(0, ir.I64()) // undef
	}
	return s[len(s)-1]
}

// Value의 레지스터 이름을 스택에서 rename
func renameValue(v *ir.Value, stacks map[string][]*ir.Value) *ir.Value {
	if v == nil || v.Kind != ir.ValReg {
		return v
	}
	s := stacks[v.Name]
	if len(s) == 0 {
		return v
	}
	return s[len(s)-1]
}

// instruction의 모든 operand를 rename
func renameInst(inst *ir.Inst, stacks map[string][]*ir.Value) {
	rv := func(v *ir.Value) *ir.Value { return renameValue(v, stacks) }
	switch inst.Kind {
	case ir.InstBinop, ir.InstICmp, ir.InstFCmp:
		inst.LHS = rv(inst.LHS)
		inst.RHS = rv(inst.RHS)
	case ir.InstNeg, ir.InstCast:
		inst.Operand = rv(inst.Operand)
	case ir.InstLoad:
		inst.Ptr = rv(inst.Ptr)
	case ir.InstStore:
		inst.Val = rv(inst.Val)
		inst.Ptr = rv(inst.Ptr)
	case ir.InstGEP:
		inst.Ptr = rv(inst.Ptr)
		inst.Idx = rv(inst.Idx)
	case ir.InstCall:
		for i, a := range inst.Args {
			inst.Args[i] = rv(a)
		}
	case ir.InstBrCond:
		inst.Cond = rv(inst.Cond)
	case ir.InstRet:
		inst.Val = rv(inst.Val)
	case ir.InstPhi:
		for i := range inst.Incoming {
			inst.Incoming[i].Val = rv(inst.Incoming[i].Val)
		}
	}
}

