package main

import (
	"fmt"
	"fir/src/irgen"
	"fir/src/ir"
)

func successors(b *ir.Block) []string {
	if len(b.Insts) == 0 { return nil }
	last := b.Insts[len(b.Insts)-1]
	switch last.Kind {
	case ir.InstBr:     return []string{last.Target}
	case ir.InstBrCond: return []string{last.TrueLabel, last.FalseLabel}
	}
	return nil
}

func buildPreds(fn *ir.Function) map[string][]string {
	preds := make(map[string][]string)
	for _, b := range fn.Blocks { preds[b.Label] = nil }
	for _, b := range fn.Blocks {
		for _, succ := range successors(b) {
			preds[succ] = append(preds[succ], b.Label)
		}
	}
	return preds
}

func reversePostOrder(fn *ir.Function) []string {
	blockMap := make(map[string]*ir.Block)
	for _, b := range fn.Blocks { blockMap[b.Label] = b }
	visited := map[string]bool{}
	postOrder := []string{}
	var dfs func(label string)
	dfs = func(label string) {
		if visited[label] { return }
		visited[label] = true
		b, ok := blockMap[label]
		if !ok { return }
		for _, succ := range successors(b) { dfs(succ) }
		postOrder = append(postOrder, label)
	}
	dfs(fn.Blocks[0].Label)
	rpo := make([]string, len(postOrder))
	for i, label := range postOrder { rpo[len(postOrder)-1-i] = label }
	return rpo
}

func intersect(b1, b2 string, idom map[string]string, rpoIndex map[string]int) string {
	f1, f2 := b1, b2
	for f1 != f2 {
		for rpoIndex[f1] > rpoIndex[f2] { f1 = idom[f1] }
		for rpoIndex[f2] > rpoIndex[f1] { f2 = idom[f2] }
	}
	return f1
}

func computeIDom(fn *ir.Function, preds map[string][]string) map[string]string {
	rpo := reversePostOrder(fn)
	rpoIndex := make(map[string]int)
	for i, label := range rpo { rpoIndex[label] = i }
	entry := fn.Blocks[0].Label
	idom := make(map[string]string)
	idom[entry] = entry
	changed := true
	for changed {
		changed = false
		for _, label := range rpo {
			if label == entry { continue }
			newIdom := ""
			for _, p := range preds[label] {
				if idom[p] == "" { continue }
				if newIdom == "" { newIdom = p; continue }
				newIdom = intersect(newIdom, p, idom, rpoIndex)
			}
			if newIdom == "" { newIdom = entry }
			if idom[label] != newIdom { idom[label] = newIdom; changed = true }
		}
	}
	return idom
}

func contains(slice []string, s string) bool {
	for _, v := range slice { if v == s { return true } }
	return false
}

func computeDF(fn *ir.Function, preds map[string][]string, idom map[string]string) map[string][]string {
	df := make(map[string][]string)
	for _, b := range fn.Blocks {
		ps := preds[b.Label]
		if len(ps) < 2 { continue }
		for _, p := range ps {
			runner := p
			for runner != idom[b.Label] {
				if !contains(df[runner], b.Label) {
					df[runner] = append(df[runner], b.Label)
				}
				next := idom[runner]
				if next == runner || next == "" { break }
				runner = next
			}
		}
	}
	return df
}

func main() {
	src := `fn f(x: i64) -> i64 {
		let r: i64 = 0
		if x > 0 { r = 1 } else { r = -1 }
		return r
	}`
	mod, _ := irgen.Compile(src)
	fn := mod.Functions[0]

	fmt.Println("=== Raw IR ===")
	fmt.Println(mod)

	preds := buildPreds(fn)
	rpo := reversePostOrder(fn)
	idom := computeIDom(fn, preds)
	df := computeDF(fn, preds, idom)

	fmt.Println("RPO:", rpo)
	fmt.Println("idom:", idom)
	fmt.Println("DF:", df)

	// defsIn 수집
	promotable := map[string]bool{"r_ptr": true, "x_ptr": true}
	defsIn := map[string][]string{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstStore {
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					if !contains(defsIn[inst.Ptr.Name], b.Label) {
						defsIn[inst.Ptr.Name] = append(defsIn[inst.Ptr.Name], b.Label)
					}
				}
			}
		}
	}
	fmt.Println("defsIn:", defsIn)
}
