// ----------------------------------------------------------------
// 6. rename 패스
// ----------------------------------------------------------------

// stacks[allocaName] = []값 스택 (alloca 전용)
// env[regName] = 치환 값 (load result alias, 블록 경계 무관)
func rename(fn *ir.Function, blockMap map[string]*ir.Block,
	idom map[string]string, promotable map[string]bool,
	phiMap map[string]map[string]*phiInfo) {

	// dominator tree children
	domChildren := map[string][]string{}
	for _, b := range fn.Blocks {
		dom := idom[b.Label]
		if dom != "" && dom != b.Label {
			domChildren[dom] = append(domChildren[dom], b.Label)
		}
	}

	// alloca 타입
	allocaType := map[string]*ir.Type{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca && promotable[inst.Result] {
				allocaType[inst.Result] = inst.AllocType
			}
		}
	}

	// stacks: alloca 이름 → []값 (SSA 스택)
	stacks := map[string][]*ir.Value{}

	// env: 레지스터 이름 → 치환 값
	// load result를 alloca top으로 alias하기 위해 사용
	// 블록 경계를 넘지 않아도 되는 이유:
	//   dominator tree 순서로 rename하므로 def가 dom 블록에서 먼저 처리됨
	//   단, load는 제거되므로 result name → actual value 매핑이 필요
	env := map[string]*ir.Value{}

	// env 기반 값 치환 (alloca stacks + env 순서)
	resolve := func(v *ir.Value) *ir.Value {
		if v == nil || v.Kind != ir.ValReg {
			return v
		}
		// env에 alias가 있으면 우선
		if cv, ok := env[v.Name]; ok {
			return cv
		}
		return v
	}

	resolveInst := func(inst *ir.Inst) {
		rv := resolve
		switch inst.Kind {
		case ir.InstBinop, ir.InstICmp, ir.InstFCmp:
			inst.LHS = rv(inst.LHS)
			inst.RHS = rv(inst.RHS)
		case ir.InstNeg, ir.InstCast:
			inst.Operand = rv(inst.Operand)
		case ir.InstLoad:
			inst.Ptr = rv(inst.Ptr)
		case ir.InstStore:
			inst.Val = rv(inst.Val)
			inst.Ptr = rv(inst.Ptr)
		case ir.InstGEP:
			inst.Ptr = rv(inst.Ptr)
			inst.Idx = rv(inst.Idx)
		case ir.InstCall:
			for i, a := range inst.Args { inst.Args[i] = rv(a) }
		case ir.InstBrCond:
			inst.Cond = rv(inst.Cond)
		case ir.InstRet:
			inst.Val = rv(inst.Val)
		case ir.InstPhi:
			for i := range inst.Incoming {
				inst.Incoming[i].Val = rv(inst.Incoming[i].Val)
			}
		}
	}

	var renameBlock func(label string)
	renameBlock = func(label string) {
		b, ok := blockMap[label]
		if !ok {
			return
		}

		// 이 블록에서 stacks에 push한 alloca 이름 목록 (pop용)
		var pushedAlloca []string

		newInsts := []*ir.Inst{}
		for _, inst := range b.Insts {
			switch inst.Kind {

			case ir.InstAlloca:
				if promotable[inst.Result] {
					// undef 초기값 (실제로 쓰이기 전에 store가 반드시 옴)
					undef := ir.ConstInt(0, allocaType[inst.Result])
					stacks[inst.Result] = append(stacks[inst.Result], undef)
					pushedAlloca = append(pushedAlloca, inst.Result)
					// alloca 제거
					continue
				}
				newInsts = append(newInsts, inst)

			case ir.InstStore:
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					allocaName := inst.Ptr.Name
					// store 값 resolve (다른 load alias 반영)
					val := resolve(inst.Val)
					stacks[allocaName] = append(stacks[allocaName], val)
					pushedAlloca = append(pushedAlloca, allocaName)
					// store 제거
					continue
				}
				resolveInst(inst)
				newInsts = append(newInsts, inst)

			case ir.InstLoad:
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					allocaName := inst.Ptr.Name
					top := currentDef(stacks, allocaName)
					// load result → top으로 env에 등록 (블록 경계 무관)
					env[inst.Result] = top
					// load 제거
					continue
				}
				resolveInst(inst)
				newInsts = append(newInsts, inst)

			case ir.InstPhi:
				// phi result → phi 자신의 레지스터를 현재 def로 등록
				// (successor phi incoming 채울 때 이 블록에서 쓰인 값은 stacks에서 옴)
				resolveInst(inst)
				stacks[inst.Result] = append(stacks[inst.Result], ir.Reg(inst.Result, inst.Type))
				pushedAlloca = append(pushedAlloca, inst.Result)
				newInsts = append(newInsts, inst)

			default:
				resolveInst(inst)
				newInsts = append(newInsts, inst)
			}
		}
		b.Insts = newInsts

		// successor의 phi incoming 채우기
		for _, succLabel := range successors(b) {
			succPhis := phiMap[succLabel]
			succBlock, ok2 := blockMap[succLabel]
			if !ok2 {
				continue
			}
			for allocaName, info := range succPhis {
				top := currentDef(stacks, allocaName)
				for _, inst := range succBlock.Insts {
					if inst.Kind == ir.InstPhi && inst.Result == info.result {
						inst.Incoming = append(inst.Incoming, ir.PhiIncoming{
							Val:   top,
							Block: label,
						})
						break
					}
				}
			}
		}

		// dominator tree children 재귀 방문
		for _, child := range domChildren[label] {
			renameBlock(child)
		}

		// 이 블록에서 push한 alloca 스택 pop (역순)
		for i := len(pushedAlloca) - 1; i >= 0; i-- {
			name := pushedAlloca[i]
			if len(stacks[name]) > 0 {
				stacks[name] = stacks[name][:len(stacks[name])-1]
			}
		}
	}

	if len(fn.Blocks) > 0 {
		renameBlock(fn.Blocks[0].Label)
	}

	// phi incoming 0개 phi 제거
	for _, b := range fn.Blocks {
		cleaned := b.Insts[:0]
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstPhi && len(inst.Incoming) == 0 {
				continue
			}
			cleaned = append(cleaned, inst)
		}
		b.Insts = cleaned
	}
}

