     1→// fir Optimizer — P3.1 mem2reg (alloca → SSA phi)
     2→//
     3→// 알고리즘: Cytron et al. (1991) SSA 변환 — 교과서 표준 구현
     4→//
     5→//   1. promotable alloca 탐지
     6→//      조건: ptr이 load/store에만 쓰이고 address-taken 아님
     7→//
     8→//   2. CFG 구성 (predecessors)
     9→//
    10→//   3. Dominance 계산 (iterative dataflow — 역후위순서)
    11→//
    12→//   4. Dominance Frontier 계산
    13→//
    14→//   5. phi 삽입
    15→//      - 각 alloca 변수의 store 위치에서 DF 계산
    16→//      - frontier 블록에 phi 노드 삽입
    17→//      - phi 삽입이 새 DF를 만들 수 있으므로 수렴까지 반복
    18→//
    19→//   6. rename 패스 (DFS, dominator tree 순서)
    20→//      - alloca 제거
    21→//      - store → 현재 def 갱신 (instruction 제거)
    22→//      - load  → 현재 def 값으로 치환 (instruction 제거)
    23→//      - phi   → incoming 값 연결
    24→package opt
    25→
    26→import (
    27→	"fmt"
    28→	"fir/src/ir"
    29→)
    30→
    31→// ----------------------------------------------------------------
    32→// Mem2RegPass
    33→// ----------------------------------------------------------------
    34→
    35→type Mem2RegPass struct{}
    36→
    37→func (p *Mem2RegPass) Name() string { return "mem2reg" }
    38→
    39→func (p *Mem2RegPass) Run(mod *ir.Module) *ir.Module {
    40→	for _, fn := range mod.Functions {
    41→		if len(fn.Blocks) > 0 {
    42→			mem2regFunc(fn)
    43→		}
    44→	}
    45→	return mod
    46→}
    47→
    48→// ----------------------------------------------------------------
    49→// 함수 단위 mem2reg
    50→// ----------------------------------------------------------------
    51→
    52→func mem2regFunc(fn *ir.Function) {
    53→	// 1. promotable alloca 탐지
    54→	promotable := findPromotable(fn)
    55→	if len(promotable) == 0 {
    56→		return
    57→	}
    58→
    59→	// 2. CFG: label → Block, predecessors
    60→	blockMap := make(map[string]*ir.Block)
    61→	for _, b := range fn.Blocks {
    62→		blockMap[b.Label] = b
    63→	}
    64→	preds := buildPreds(fn, blockMap)
    65→
    66→	// 3. Dominance 계산
    67→	idom := computeIDom(fn, preds)
    68→
    69→	// 4. Dominance Frontier 계산
    70→	df := computeDF(fn, preds, idom)
    71→
    72→	// 5. phi 삽입
    73→	phiMap := insertPhis(fn, blockMap, df, promotable)
    74→
    75→	// 6. rename
    76→	rename(fn, blockMap, idom, promotable, phiMap)
    77→}
    78→
    79→// ----------------------------------------------------------------
    80→// 1. Promotable alloca 탐지
    81→// ----------------------------------------------------------------
    82→
    83→// alloca가 승격 가능한지: load/store에만 쓰이고 address-taken 아님
    84→func findPromotable(fn *ir.Function) map[string]bool {
    85→	// alloca 집합 수집
    86→	allocas := map[string]bool{}
    87→	for _, b := range fn.Blocks {
    88→		for _, inst := range b.Insts {
    89→			if inst.Kind == ir.InstAlloca {
    90→				allocas[inst.Result] = true
    91→			}
    92→		}
    93→	}
    94→
    95→	// non-promotable 표시: load/store 이외 용도로 쓰이면 제외
    96→	notPromotable := map[string]bool{}
    97→	for _, b := range fn.Blocks {
    98→		for _, inst := range b.Insts {
    99→			switch inst.Kind {
   100→			case ir.InstLoad:
   101→				// ptr이 alloca → OK
   102→			case ir.InstStore:
   103→				// ptr이 alloca → OK (val은 상관없음)
   104→				// val이 alloca 주소이면 address-taken → 제외
   105→				if inst.Val != nil && inst.Val.Kind == ir.ValReg && allocas[inst.Val.Name] {
   106→					notPromotable[inst.Val.Name] = true
   107→				}
   108→			case ir.InstAlloca:
   109→				// alloca 자체
   110→			default:
   111→				// 다른 instruction에서 alloca ptr 사용 → address-taken
   112→				for _, reg := range usedRegs(inst) {
   113→					if allocas[reg] {
   114→						notPromotable[reg] = true
   115→					}
   116→				}
   117→			}
   118→		}
   119→	}
   120→
   121→	promotable := map[string]bool{}
   122→	for name := range allocas {
   123→		if !notPromotable[name] {
   124→			promotable[name] = true
   125→		}
   126→	}
   127→	return promotable
   128→}
   129→
   130→// ----------------------------------------------------------------
   131→// 2. CFG — predecessors
   132→// ----------------------------------------------------------------
   133→
   134→func buildPreds(fn *ir.Function, blockMap map[string]*ir.Block) map[string][]string {
   135→	preds := make(map[string][]string)
   136→	for _, b := range fn.Blocks {
   137→		preds[b.Label] = nil // 초기화
   138→	}
   139→	for _, b := range fn.Blocks {
   140→		for _, succ := range successors(b) {
   141→			preds[succ] = append(preds[succ], b.Label)
   142→		}
   143→	}
   144→	return preds
   145→}
   146→
   147→// ----------------------------------------------------------------
   148→// 3. Dominance — iterative dataflow
   149→// ----------------------------------------------------------------
   150→
   151→// idom[b] = b의 immediate dominator label ("" = entry 또는 미확정)
   152→func computeIDom(fn *ir.Function, preds map[string][]string) map[string]string {
   153→	if len(fn.Blocks) == 0 {
   154→		return nil
   155→	}
   156→
   157→	// 역후위순서 (reverse post-order) 계산
   158→	rpo := reversePostOrder(fn)
   159→	rpoIndex := make(map[string]int)
   160→	for i, label := range rpo {
   161→		rpoIndex[label] = i
   162→	}
   163→
   164→	entry := fn.Blocks[0].Label
   165→	idom := make(map[string]string)
   166→	idom[entry] = entry // entry dominates itself
   167→
   168→	// Cooper et al. 단순 iterative dominator 알고리즘
   169→	changed := true
   170→	for changed {
   171→		changed = false
   172→		for _, label := range rpo {
   173→			if label == entry {
   174→				continue
   175→			}
   176→			// 처리된 predecessor 중 첫 번째
   177→			newIdom := ""
   178→			for _, p := range preds[label] {
   179→				if idom[p] == "" {
   180→					continue
   181→				}
   182→				if newIdom == "" {
   183→					newIdom = p
   184→					continue
   185→				}
   186→				// intersect(newIdom, p)
   187→				newIdom = intersect(newIdom, p, idom, rpoIndex)
   188→			}
   189→			if newIdom == "" {
   190→				newIdom = entry
   191→			}
   192→			if idom[label] != newIdom {
   193→				idom[label] = newIdom
   194→				changed = true
   195→			}
   196→		}
   197→	}
   198→	return idom
   199→}
   200→
   201→func intersect(b1, b2 string, idom map[string]string, rpoIndex map[string]int) string {
   202→	finger1, finger2 := b1, b2
   203→	for finger1 != finger2 {
   204→		for rpoIndex[finger1] > rpoIndex[finger2] {
   205→			finger1 = idom[finger1]
   206→		}
   207→		for rpoIndex[finger2] > rpoIndex[finger1] {
   208→			finger2 = idom[finger2]
   209→		}
   210→	}
   211→	return finger1
   212→}
   213→
   214→// DFS 기반 역후위순서
   215→func reversePostOrder(fn *ir.Function) []string {
   216→	if len(fn.Blocks) == 0 {
   217→		return nil
   218→	}
   219→	blockMap := make(map[string]*ir.Block)
   220→	for _, b := range fn.Blocks {
   221→		blockMap[b.Label] = b
   222→	}
   223→
   224→	visited := map[string]bool{}
   225→	postOrder := []string{}
   226→
   227→	var dfs func(label string)
   228→	dfs = func(label string) {
   229→		if visited[label] {
   230→			return
   231→		}
   232→		visited[label] = true
   233→		b, ok := blockMap[label]
   234→		if !ok {
   235→			return
   236→		}
   237→		for _, succ := range successors(b) {
   238→			dfs(succ)
   239→		}
   240→		postOrder = append(postOrder, label)
   241→	}
   242→	dfs(fn.Blocks[0].Label)
   243→
   244→	// 역순
   245→	rpo := make([]string, len(postOrder))
   246→	for i, label := range postOrder {
   247→		rpo[len(postOrder)-1-i] = label
   248→	}
   249→	return rpo
   250→}
   251→
   252→// ----------------------------------------------------------------
   253→// 4. Dominance Frontier
   254→// ----------------------------------------------------------------
   255→
   256→func computeDF(fn *ir.Function, preds map[string][]string, idom map[string]string) map[string][]string {
   257→	df := make(map[string][]string)
   258→	for _, b := range fn.Blocks {
   259→		ps := preds[b.Label]
   260→		if len(ps) < 2 {
   261→			continue
   262→		}
   263→		// b가 join point
   264→		for _, p := range ps {
   265→			runner := p
   266→			for runner != idom[b.Label] {
   267→				// runner의 DF에 b 추가
   268→				if !contains(df[runner], b.Label) {
   269→					df[runner] = append(df[runner], b.Label)
   270→				}
   271→				next := idom[runner]
   272→				if next == runner || next == "" {
   273→					break
   274→				}
   275→				runner = next
   276→			}
   277→		}
   278→	}
   279→	return df
   280→}
   281→
   282→func contains(slice []string, s string) bool {
   283→	for _, v := range slice {
   284→		if v == s {
   285→			return true
   286→		}
   287→	}
   288→	return false
   289→}
   290→
   291→// ----------------------------------------------------------------
   292→// 5. phi 삽입
   293→// ----------------------------------------------------------------
   294→
   295→// phiMap[blockLabel][allocaName] = phi instruction result name
   296→type phiInfo struct {
   297→	result string
   298→	irType *ir.Type
   299→}
   300→
   301→func insertPhis(fn *ir.Function, blockMap map[string]*ir.Block,
   302→	df map[string][]string, promotable map[string]bool) map[string]map[string]*phiInfo {
   303→
   304→	// alloca 타입 수집
   305→	allocaType := map[string]*ir.Type{}
   306→	for _, b := range fn.Blocks {
   307→		for _, inst := range b.Insts {
   308→			if inst.Kind == ir.InstAlloca && promotable[inst.Result] {
   309→				allocaType[inst.Result] = inst.AllocType
   310→			}
   311→		}
   312→	}
   313→
   314→	// 각 alloca 변수의 store 위치 수집
   315→	defsIn := map[string][]string{} // allocaName → []blockLabel
   316→	for _, b := range fn.Blocks {
   317→		for _, inst := range b.Insts {
   318→			if inst.Kind == ir.InstStore {
   319→				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
   320→					if !contains(defsIn[inst.Ptr.Name], b.Label) {
   321→						defsIn[inst.Ptr.Name] = append(defsIn[inst.Ptr.Name], b.Label)
   322→					}
   323→				}
   324→			}
   325→		}
   326→	}
   327→
   328→	// phiMap[block][alloca] = phiInfo
   329→	phiMap := map[string]map[string]*phiInfo{}
   330→	for _, b := range fn.Blocks {
   331→		phiMap[b.Label] = map[string]*phiInfo{}
   332→	}
   333→
   334→	// phi 삽입 카운터
   335→	phiCounter := 0
   336→
   337→	for allocaName, defBlocks := range defsIn {
   338→		irT := allocaType[allocaName]
   339→		if irT == nil {
   340→			continue
   341→		}
   342→
   343→		worklist := make([]string, len(defBlocks))
   344→		copy(worklist, defBlocks)
   345→		hasPhiFor := map[string]bool{}
   346→
   347→		for len(worklist) > 0 {
   348→			b := worklist[0]
   349→			worklist = worklist[1:]
   350→			for _, frontier := range df[b] {
   351→				if hasPhiFor[frontier] {
   352→					continue
   353→				}
   354→				hasPhiFor[frontier] = true
   355→				// phi 삽입
   356→				result := fmt.Sprintf("phi_%s_%d", allocaName, phiCounter)
   357→				phiCounter++
   358→				phiMap[frontier][allocaName] = &phiInfo{result: result, irType: irT}
   359→				// frontier도 def 블록이 됨 → worklist에 추가
   360→				worklist = append(worklist, frontier)
   361→			}
   362→		}
   363→	}
   364→
   365→	// 실제 phi instruction을 블록 앞에 삽입 (incoming은 rename에서 채움)
   366→	for _, b := range fn.Blocks {
   367→		phis := phiMap[b.Label]
   368→		if len(phis) == 0 {
   369→			continue
   370→		}
   371→		var phiInsts []*ir.Inst
   372→		for _, info := range phis {
   373→			phiInsts = append(phiInsts, ir.NewPhi(info.result, info.irType, nil))
   374→		}
   375→		b.Insts = append(phiInsts, b.Insts...)
   376→	}
   377→
   378→	return phiMap
   379→}
   380→
   381→// ----------------------------------------------------------------
   382→// 6. rename 패스
   383→// ----------------------------------------------------------------
   384→
   385→// stacks[allocaName] = []값 스택 (alloca 전용)
   386→// env[regName] = 치환 값 (load result alias, 블록 경계 무관)
   387→func rename(fn *ir.Function, blockMap map[string]*ir.Block,
   388→	idom map[string]string, promotable map[string]bool,
   389→	phiMap map[string]map[string]*phiInfo) {
   390→
   391→	// dominator tree children
   392→	domChildren := map[string][]string{}
   393→	for _, b := range fn.Blocks {
   394→		dom := idom[b.Label]
   395→		if dom != "" && dom != b.Label {
   396→			domChildren[dom] = append(domChildren[dom], b.Label)
   397→		}
   398→	}
   399→
   400→	// alloca 타입
   401→	allocaType := map[string]*ir.Type{}
   402→	for _, b := range fn.Blocks {
   403→		for _, inst := range b.Insts {
   404→			if inst.Kind == ir.InstAlloca && promotable[inst.Result] {
   405→				allocaType[inst.Result] = inst.AllocType
   406→			}
   407→		}
   408→	}
   409→
   410→	// stacks: alloca 이름 → []값 (SSA 스택)
   411→	stacks := map[string][]*ir.Value{}
   412→
   413→	// env: 레지스터 이름 → 치환 값
   414→	// load result를 alloca top으로 alias하기 위해 사용
   415→	// 블록 경계를 넘지 않아도 되는 이유:
   416→	//   dominator tree 순서로 rename하므로 def가 dom 블록에서 먼저 처리됨
   417→	//   단, load는 제거되므로 result name → actual value 매핑이 필요
   418→	env := map[string]*ir.Value{}
   419→
   420→	// env 기반 값 치환 (alloca stacks + env 순서)
   421→	resolve := func(v *ir.Value) *ir.Value {
   422→		if v == nil || v.Kind != ir.ValReg {
   423→			return v
   424→		}
   425→		// env에 alias가 있으면 우선
   426→		if cv, ok := env[v.Name]; ok {
   427→			return cv
   428→		}
   429→		return v
   430→	}
   431→
   432→	resolveInst := func(inst *ir.Inst) {
   433→		rv := resolve
   434→		switch inst.Kind {
   435→		case ir.InstBinop, ir.InstICmp, ir.InstFCmp:
   436→			inst.LHS = rv(inst.LHS)
   437→			inst.RHS = rv(inst.RHS)
   438→		case ir.InstNeg, ir.InstCast:
   439→			inst.Operand = rv(inst.Operand)
   440→		case ir.InstLoad:
   441→			inst.Ptr = rv(inst.Ptr)
   442→		case ir.InstStore:
   443→			inst.Val = rv(inst.Val)
   444→			inst.Ptr = rv(inst.Ptr)
   445→		case ir.InstGEP:
   446→			inst.Ptr = rv(inst.Ptr)
   447→			inst.Idx = rv(inst.Idx)
   448→		case ir.InstCall:
   449→			for i, a := range inst.Args { inst.Args[i] = rv(a) }
   450→		case ir.InstBrCond:
   451→			inst.Cond = rv(inst.Cond)
   452→		case ir.InstRet:
   453→			inst.Val = rv(inst.Val)
   454→		case ir.InstPhi:
   455→			for i := range inst.Incoming {
   456→				inst.Incoming[i].Val = rv(inst.Incoming[i].Val)
   457→			}
   458→		}
   459→	}
   460→
   461→	// phiResult → allocaName 역방향 맵 (phi가 어떤 alloca를 대표하는지)
   462→	phiToAlloca := map[string]string{}
   463→	for blockLabel, phiM := range phiMap {
   464→		_ = blockLabel
   465→		for allocaName, info := range phiM {
   466→			phiToAlloca[info.result] = allocaName
   467→		}
   468→	}
   469→
   470→	var renameBlock func(label string)
   471→	renameBlock = func(label string) {
   472→		b, ok := blockMap[label]
   473→		if !ok {
   474→			return
   475→		}
   476→
   477→		// 이 블록에서 stacks에 push한 alloca 이름 목록 (pop용)
   478→		var pushedAlloca []string
   479→
   480→		newInsts := []*ir.Inst{}
   481→		for _, inst := range b.Insts {
   482→			switch inst.Kind {
   483→
   484→			case ir.InstAlloca:
   485→				if promotable[inst.Result] {
   486→					// undef 초기값
   487→					undef := ir.ConstInt(0, allocaType[inst.Result])
   488→					stacks[inst.Result] = append(stacks[inst.Result], undef)
   489→					pushedAlloca = append(pushedAlloca, inst.Result)
   490→					// alloca 제거
   491→					continue
   492→				}
   493→				newInsts = append(newInsts, inst)
   494→
   495→			case ir.InstStore:
   496→				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
   497→					allocaName := inst.Ptr.Name
   498→					val := resolve(inst.Val)
   499→					stacks[allocaName] = append(stacks[allocaName], val)
   500→					pushedAlloca = append(pushedAlloca, allocaName)
   501→					// store 제거
   502→					continue
   503→				}
   504→				resolveInst(inst)
   505→				newInsts = append(newInsts, inst)
   506→
   507→			case ir.InstLoad:
   508→				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
   509→					allocaName := inst.Ptr.Name
   510→					top := currentDef(stacks, allocaName)
   511→					// load result를 top으로 env에 등록
   512→					env[inst.Result] = top
   513→					// load 제거
   514→					continue
   515→				}
   516→				resolveInst(inst)
   517→				newInsts = append(newInsts, inst)
   518→
   519→			case ir.InstPhi:
   520→				resolveInst(inst)
   521→				// phi가 alloca를 대표하면 해당 alloca 스택에 push
   522→				if allocaName, ok2 := phiToAlloca[inst.Result]; ok2 {
   523→					phiVal := ir.Reg(inst.Result, inst.Type)
   524→					stacks[allocaName] = append(stacks[allocaName], phiVal)
   525→					pushedAlloca = append(pushedAlloca, allocaName)
   526→				}
   527→				newInsts = append(newInsts, inst)
   528→
   529→			default:
   530→				resolveInst(inst)
   531→				newInsts = append(newInsts, inst)
   532→			}
   533→		}
   534→		b.Insts = newInsts
   535→
   536→		// successor의 phi incoming 채우기
   537→		for _, succLabel := range successors(b) {
   538→			succPhis := phiMap[succLabel]
   539→			succBlock, ok2 := blockMap[succLabel]
   540→			if !ok2 {
   541→				continue
   542→			}
   543→			for allocaName, info := range succPhis {
   544→				top := currentDef(stacks, allocaName)
   545→				for _, inst := range succBlock.Insts {
   546→					if inst.Kind == ir.InstPhi && inst.Result == info.result {
   547→						inst.Incoming = append(inst.Incoming, ir.PhiIncoming{
   548→							Val:   top,
   549→							Block: label,
   550→						})
   551→						break
   552→					}
   553→				}
   554→			}
   555→		}
   556→
   557→		// dominator tree children 재귀 방문
   558→		for _, child := range domChildren[label] {
   559→			renameBlock(child)
   560→		}
   561→
   562→		// 이 블록에서 push한 alloca 스택 pop (역순)
   563→		for i := len(pushedAlloca) - 1; i >= 0; i-- {
   564→			name := pushedAlloca[i]
   565→			if len(stacks[name]) > 0 {
   566→				stacks[name] = stacks[name][:len(stacks[name])-1]
   567→			}
   568→		}
   569→	}
   570→
   571→	if len(fn.Blocks) > 0 {
   572→		renameBlock(fn.Blocks[0].Label)
   573→	}
   574→
   575→	// phi incoming 0개 phi 제거
   576→	for _, b := range fn.Blocks {
   577→		cleaned := b.Insts[:0]
   578→		for _, inst := range b.Insts {
   579→			if inst.Kind == ir.InstPhi && len(inst.Incoming) == 0 {
   580→				continue
   581→			}
   582→			cleaned = append(cleaned, inst)
   583→		}
   584→		b.Insts = cleaned
   585→	}
   586→}
   587→
   588→// 스택 top 반환 (없으면 undef=0)
   589→func currentDef(stacks map[string][]*ir.Value, name string) *ir.Value {
   590→	s := stacks[name]
   591→	if len(s) == 0 {
   592→		return ir.ConstInt(0, ir.I64()) // undef
   593→	}
   594→	return s[len(s)-1]
   595→}
   596→

