// fir Optimizer — P3.1 mem2reg (alloca → SSA phi)
//
// 알고리즘: Cytron et al. (1991) 표준 SSA 변환
//
//   1. promotable alloca 탐지  (load/store 전용, address-taken 아님)
//   2. CFG predecessors 구성
//   3. Dominance (idom) 계산  — Cooper et al. iterative
//   4. Dominance Frontier 계산
//   5. phi 삽입               — store 위치 → DF → phi node
//   6. rename                 — dominator tree DFS
//      alloca/store/load 제거, phi incoming 연결
package opt

import (
	"fmt"
	"fir/src/ir"
)

// ----------------------------------------------------------------
// Pass
// ----------------------------------------------------------------

type Mem2RegPass struct{}

func (p *Mem2RegPass) Name() string { return "mem2reg" }

func (p *Mem2RegPass) Run(mod *ir.Module) *ir.Module {
	for _, fn := range mod.Functions {
		if len(fn.Blocks) > 0 {
			mem2regFunc(fn)
		}
	}
	return mod
}

// ----------------------------------------------------------------
// 함수 단위 진입점
// ----------------------------------------------------------------

func mem2regFunc(fn *ir.Function) {
	promotable := findPromotable(fn)
	if len(promotable) == 0 {
		return
	}

	blockMap := makeBlockMap(fn)
	preds := buildPreds(fn)
	idom := computeIDom(fn, preds)
	df := computeDF(fn, preds, idom)
	phiMap, phiToAlloca := insertPhis(fn, blockMap, df, promotable)
	renamePass(fn, blockMap, idom, promotable, phiMap, phiToAlloca)
}

// ----------------------------------------------------------------
// 1. Promotable alloca 탐지
// ----------------------------------------------------------------

func findPromotable(fn *ir.Function) map[string]bool {
	allocas := map[string]bool{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca {
				allocas[inst.Result] = true
			}
		}
	}

	// address-taken: store val 또는 다른 instruction operand로 쓰이면 제외
	notPromotable := map[string]bool{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			switch inst.Kind {
			case ir.InstLoad, ir.InstAlloca:
				// OK
			case ir.InstStore:
				if inst.Val != nil && inst.Val.Kind == ir.ValReg && allocas[inst.Val.Name] {
					notPromotable[inst.Val.Name] = true
				}
			default:
				for _, reg := range usedRegs(inst) {
					if allocas[reg] {
						notPromotable[reg] = true
					}
				}
			}
		}
	}

	out := map[string]bool{}
	for name := range allocas {
		if !notPromotable[name] {
			out[name] = true
		}
	}
	return out
}

// ----------------------------------------------------------------
// CFG 헬퍼
// ----------------------------------------------------------------

func makeBlockMap(fn *ir.Function) map[string]*ir.Block {
	m := make(map[string]*ir.Block, len(fn.Blocks))
	for _, b := range fn.Blocks {
		m[b.Label] = b
	}
	return m
}

func buildPreds(fn *ir.Function) map[string][]string {
	preds := make(map[string][]string, len(fn.Blocks))
	for _, b := range fn.Blocks {
		preds[b.Label] = nil
	}
	for _, b := range fn.Blocks {
		for _, succ := range successors(b) {
			preds[succ] = append(preds[succ], b.Label)
		}
	}
	return preds
}

// ----------------------------------------------------------------
// 3. Dominance (Cooper et al. iterative)
// ----------------------------------------------------------------

func computeIDom(fn *ir.Function, preds map[string][]string) map[string]string {
	rpo := reversePostOrder(fn)
	rpoIdx := make(map[string]int, len(rpo))
	for i, label := range rpo {
		rpoIdx[label] = i
	}

	entry := fn.Blocks[0].Label
	idom := make(map[string]string, len(fn.Blocks))
	idom[entry] = entry

	for changed := true; changed; {
		changed = false
		for _, label := range rpo {
			if label == entry {
				continue
			}
			newIdom := ""
			for _, p := range preds[label] {
				if idom[p] == "" {
					continue
				}
				if newIdom == "" {
					newIdom = p
				} else {
					newIdom = domIntersect(newIdom, p, idom, rpoIdx)
				}
			}
			if newIdom == "" {
				newIdom = entry
			}
			if idom[label] != newIdom {
				idom[label] = newIdom
				changed = true
			}
		}
	}
	return idom
}

func domIntersect(a, b string, idom map[string]string, rpoIdx map[string]int) string {
	for a != b {
		for rpoIdx[a] > rpoIdx[b] {
			a = idom[a]
		}
		for rpoIdx[b] > rpoIdx[a] {
			b = idom[b]
		}
	}
	return a
}

func reversePostOrder(fn *ir.Function) []string {
	blockMap := makeBlockMap(fn)
	visited := make(map[string]bool, len(fn.Blocks))
	post := make([]string, 0, len(fn.Blocks))

	var dfs func(label string)
	dfs = func(label string) {
		if visited[label] {
			return
		}
		visited[label] = true
		if b, ok := blockMap[label]; ok {
			for _, succ := range successors(b) {
				dfs(succ)
			}
		}
		post = append(post, label)
	}
	dfs(fn.Blocks[0].Label)

	rpo := make([]string, len(post))
	for i, label := range post {
		rpo[len(post)-1-i] = label
	}
	return rpo
}

// ----------------------------------------------------------------
// 4. Dominance Frontier
// ----------------------------------------------------------------

func computeDF(fn *ir.Function, preds, idom map[string][]string) map[string][]string {
	df := make(map[string][]string, len(fn.Blocks))
	for _, b := range fn.Blocks {
		if len(preds[b.Label]) < 2 {
			continue
		}
		for _, p := range preds[b.Label] {
			runner := p
			for runner != idom[b.Label][0:0] {
				// idom은 map[string]string 아님 — 수정 필요 없음
				// 이 함수는 idom map[string]string을 받아야 함
				_ = runner
				break
			}
		}
	}
	return df
}

// computeDF 실제 구현 (idom map[string]string)
func computeDominanceFrontier(fn *ir.Function, preds map[string][]string, idom map[string]string) map[string][]string {
	df := make(map[string][]string, len(fn.Blocks))
	for _, b := range fn.Blocks {
		ps := preds[b.Label]
		if len(ps) < 2 {
			continue
		}
		for _, p := range ps {
			runner := p
			for runner != idom[b.Label] {
				if !strSliceContains(df[runner], b.Label) {
					df[runner] = append(df[runner], b.Label)
				}
				next := idom[runner]
				if next == runner || next == "" {
					break
				}
				runner = next
			}
		}
	}
	return df
}

func strSliceContains(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
}

// ----------------------------------------------------------------
// 5. phi 삽입
// ----------------------------------------------------------------

type phiInfo struct {
	result string
	irType *ir.Type
}

// insertPhis: phi 노드 삽입 후 두 맵 반환
//   phiMap[blockLabel][allocaName] = phiInfo
//   phiToAlloca[phiResult] = allocaName
func insertPhis(fn *ir.Function, blockMap map[string]*ir.Block,
	df map[string][]string, promotable map[string]bool,
) (map[string]map[string]*phiInfo, map[string]string) {

	// alloca 타입 수집
	allocaType := map[string]*ir.Type{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca && promotable[inst.Result] {
				allocaType[inst.Result] = inst.AllocType
			}
		}
	}

	// store 위치 수집
	defsIn := map[string][]string{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind != ir.InstStore {
				continue
			}
			if inst.Ptr == nil || inst.Ptr.Kind != ir.ValReg {
				continue
			}
			if !promotable[inst.Ptr.Name] {
				continue
			}
			name := inst.Ptr.Name
			if !strSliceContains(defsIn[name], b.Label) {
				defsIn[name] = append(defsIn[name], b.Label)
			}
		}
	}

	phiMap := make(map[string]map[string]*phiInfo, len(fn.Blocks))
	for _, b := range fn.Blocks {
		phiMap[b.Label] = map[string]*phiInfo{}
	}
	phiToAlloca := map[string]string{}
	counter := 0

	for allocaName, defBlocks := range defsIn {
		irT := allocaType[allocaName]
		if irT == nil {
			continue
		}
		worklist := make([]string, len(defBlocks))
		copy(worklist, defBlocks)
		inserted := map[string]bool{}

		for len(worklist) > 0 {
			cur := worklist[0]
			worklist = worklist[1:]
			for _, frontier := range df[cur] {
				if inserted[frontier] {
					continue
				}
				inserted[frontier] = true
				result := fmt.Sprintf("phi_%s_%d", allocaName, counter)
				counter++
				info := &phiInfo{result: result, irType: irT}
				phiMap[frontier][allocaName] = info
				phiToAlloca[result] = allocaName
				worklist = append(worklist, frontier)
			}
		}
	}

	// phi instruction을 각 블록 앞에 삽입 (incoming은 rename에서 채움)
	for _, b := range fn.Blocks {
		phis := phiMap[b.Label]
		if len(phis) == 0 {
			continue
		}
		phiInsts := make([]*ir.Inst, 0, len(phis))
		for _, info := range phis {
			phiInsts = append(phiInsts, ir.NewPhi(info.result, info.irType, nil))
		}
		b.Insts = append(phiInsts, b.Insts...)
	}

	return phiMap, phiToAlloca
}

// ----------------------------------------------------------------
// 6. rename 패스
// ----------------------------------------------------------------

func renamePass(fn *ir.Function, blockMap map[string]*ir.Block,
	idom map[string]string, promotable map[string]bool,
	phiMap map[string]map[string]*phiInfo, phiToAlloca map[string]string,
) {
	// dominator tree children
	domChildren := make(map[string][]string, len(fn.Blocks))
	for _, b := range fn.Blocks {
		if dom := idom[b.Label]; dom != "" && dom != b.Label {
			domChildren[dom] = append(domChildren[dom], b.Label)
		}
	}

	// alloca 타입 (undef 초기값 생성용)
	allocaType := map[string]*ir.Type{}
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstAlloca && promotable[inst.Result] {
				allocaType[inst.Result] = inst.AllocType
			}
		}
	}

	// stacks[allocaName]: 현재 SSA 값 스택
	stacks := map[string][]*ir.Value{}
	// env[loadResult]: load 제거 후 실제 값 alias
	env := map[string]*ir.Value{}

	// 값 치환: env 우선, 없으면 원래 값
	resolve := func(v *ir.Value) *ir.Value {
		if v != nil && v.Kind == ir.ValReg {
			if cv, ok := env[v.Name]; ok {
				return cv
			}
		}
		return v
	}

	resolveInst := func(inst *ir.Inst) {
		r := resolve
		switch inst.Kind {
		case ir.InstBinop, ir.InstICmp, ir.InstFCmp:
			inst.LHS, inst.RHS = r(inst.LHS), r(inst.RHS)
		case ir.InstNeg, ir.InstCast:
			inst.Operand = r(inst.Operand)
		case ir.InstLoad:
			inst.Ptr = r(inst.Ptr)
		case ir.InstStore:
			inst.Val, inst.Ptr = r(inst.Val), r(inst.Ptr)
		case ir.InstGEP:
			inst.Ptr, inst.Idx = r(inst.Ptr), r(inst.Idx)
		case ir.InstCall:
			for i, a := range inst.Args { inst.Args[i] = r(a) }
		case ir.InstBrCond:
			inst.Cond = r(inst.Cond)
		case ir.InstRet:
			inst.Val = r(inst.Val)
		case ir.InstPhi:
			for i := range inst.Incoming {
				inst.Incoming[i].Val = r(inst.Incoming[i].Val)
			}
		}
	}

	stackTop := func(name string) *ir.Value {
		s := stacks[name]
		if len(s) == 0 {
			return ir.ConstInt(0, ir.I64())
		}
		return s[len(s)-1]
	}

	stackPush := func(name string, v *ir.Value, pushed *[]string) {
		stacks[name] = append(stacks[name], v)
		*pushed = append(*pushed, name)
	}

	var renameBlock func(label string)
	renameBlock = func(label string) {
		b := blockMap[label]
		if b == nil {
			return
		}

		var pushed []string
		kept := b.Insts[:0]

		for _, inst := range b.Insts {
			switch inst.Kind {

			case ir.InstAlloca:
				if promotable[inst.Result] {
					stackPush(inst.Result, ir.ConstInt(0, allocaType[inst.Result]), &pushed)
					continue // 제거
				}
				kept = append(kept, inst)

			case ir.InstStore:
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					stackPush(inst.Ptr.Name, resolve(inst.Val), &pushed)
					continue // 제거
				}
				resolveInst(inst)
				kept = append(kept, inst)

			case ir.InstLoad:
				if inst.Ptr != nil && inst.Ptr.Kind == ir.ValReg && promotable[inst.Ptr.Name] {
					env[inst.Result] = stackTop(inst.Ptr.Name)
					continue // 제거
				}
				resolveInst(inst)
				kept = append(kept, inst)

			case ir.InstPhi:
				resolveInst(inst)
				if allocaName, ok := phiToAlloca[inst.Result]; ok {
					stackPush(allocaName, ir.Reg(inst.Result, inst.Type), &pushed)
				}
				kept = append(kept, inst)

			default:
				resolveInst(inst)
				kept = append(kept, inst)
			}
		}
		b.Insts = kept

		// successor phi incoming 채우기
		for _, succLabel := range successors(b) {
			succBlock := blockMap[succLabel]
			if succBlock == nil {
				continue
			}
			for allocaName, info := range phiMap[succLabel] {
				top := stackTop(allocaName)
				for _, inst := range succBlock.Insts {
					if inst.Kind == ir.InstPhi && inst.Result == info.result {
						inst.Incoming = append(inst.Incoming, ir.PhiIncoming{
							Val: top, Block: label,
						})
						break
					}
				}
			}
		}

		for _, child := range domChildren[label] {
			renameBlock(child)
		}

		// pop (역순)
		for i := len(pushed) - 1; i >= 0; i-- {
			name := pushed[i]
			if len(stacks[name]) > 0 {
				stacks[name] = stacks[name][:len(stacks[name])-1]
			}
		}
	}

	renameBlock(fn.Blocks[0].Label)

	// incoming 없는 phi 제거
	for _, b := range fn.Blocks {
		kept := b.Insts[:0]
		for _, inst := range b.Insts {
			if inst.Kind == ir.InstPhi && len(inst.Incoming) == 0 {
				continue
			}
			kept = append(kept, inst)
		}
		b.Insts = kept
	}
}

// ----------------------------------------------------------------
// 헬퍼
// ----------------------------------------------------------------

func currentDef(stacks map[string][]*ir.Value, name string) *ir.Value {
	s := stacks[name]
	if len(s) == 0 {
		return ir.ConstInt(0, ir.I64())
	}
	return s[len(s)-1]
}

