// ----------------------------------------------------------------
// TrivialPhi 테스트 헬퍼
// ----------------------------------------------------------------

func countPhis(mod *ir.Module) int {
	n := 0
	for _, fn := range mod.Functions {
		for _, b := range fn.Blocks {
			for _, inst := range b.Insts {
				if inst.Kind == ir.InstPhi {
					n++
				}
			}
		}
	}
	return n
}

func assertTrivialPhi(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | irgen: %v\n", label, err)
		optFailed++
		return
	}
	before, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | before interp: %v\n", label, err)
		optFailed++
		return
	}
	if before.AsInt() != expected {
		fmt.Printf("[FAIL] %s | before=%d expected=%d\n", label, before.AsInt(), expected)
		optFailed++
		return
	}
	nPhiBefore := countPhis(mod)

	modOpt := opt.Full().Run(mod)

	after, err := interp.ExecModule(modOpt, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | after interp: %v\n", label, err)
		optFailed++
		return
	}
	if after.AsInt() != expected {
		fmt.Printf("[FAIL] %s | after=%d expected=%d (semantics broken!)\n",
			label, after.AsInt(), expected)
		optFailed++
		return
	}
	nPhiAfter := countPhis(modOpt)
	fmt.Printf("[PASS] %s | result=%d phi: %d→%d (-%d)\n",
		label, expected, nPhiBefore, nPhiAfter, nPhiBefore-nPhiAfter)
	optPassed++
}

func testTrivialPhi() {
	fmt.Println("--- P3.5: Trivial Phi Elimination ---")

	// TP-1: 단일 블록 — phi 없음 (변화 없어야 정상)
	assertTrivialPhi("TP-1: no phi (single block)",
		`fn f(x: i64) -> i64 {
			return x + 1
		}`,
		"f", []interp.RVal{interp.RInt(41)}, 42)

	// TP-2: if 한쪽만 분기 (early return) — trivial phi 발생
	assertTrivialPhi("TP-2: early return → trivial phi",
		`fn f(x: i64) -> i64 {
			let r: i64 = 0
			if x > 0 {
				r = x
			}
			return r
		}`,
		"f", []interp.RVal{interp.RInt(7)}, 7)

	assertTrivialPhi("TP-2b: early return (zero path)",
		`fn f(x: i64) -> i64 {
			let r: i64 = 0
			if x > 0 {
				r = x
			}
			return r
		}`,
		"f", []interp.RVal{interp.RInt(-1)}, 0)

	// TP-3: if/else — 양쪽 phi (trivial 아님, phi 유지)
	assertTrivialPhi("TP-3: if/else → non-trivial phi kept",
		`fn f(x: i64) -> i64 {
			let r: i64 = 0
			if x > 0 {
				r = 1
			} else {
				r = -1
			}
			return r
		}`,
		"f", []interp.RVal{interp.RInt(5)}, 1)

	// TP-4: while 루프 (루프 phi — trivial 아님, 유지)
	assertTrivialPhi("TP-4: while loop phi kept",
		`fn sum(n: i64) -> i64 {
			let s: i64 = 0
			let i: i64 = 0
			while i < n {
				s = s + i
				i = i + 1
			}
			return s
		}`,
		"sum", []interp.RVal{interp.RInt(5)}, 10)

	// TP-5: 중첩 if — 안쪽 trivial phi가 바깥 phi로 전파
	assertTrivialPhi("TP-5: nested if trivial phi",
		`fn f(x: i64) -> i64 {
			let r: i64 = 0
			if x > 0 {
				if x > 10 {
					r = 2
				}
			}
			return r
		}`,
		"f", []interp.RVal{interp.RInt(15)}, 2)

	assertTrivialPhi("TP-5b: nested if (zero path)",
		`fn f(x: i64) -> i64 {
			let r: i64 = 0
			if x > 0 {
				if x > 10 {
					r = 2
				}
			}
			return r
		}`,
		"f", []interp.RVal{interp.RInt(3)}, 0)
}

func runOptTests() {
	fmt.Println()
	fmt.Println("=== Optimizer Tests (Phase 3) ===")

	testConstFold()
	testDCE()
	testDeadBlock()
	testMem2Reg()
	testTrivialPhi()
	testCombined()

	fmt.Println()
	fmt.Printf("Optimizer Results: %d/%d PASS\n", optPassed, optPassed+optFailed)
	if optFailed == 0 {
		fmt.Println()
		fmt.Println("OPTIMIZER VERIFIED")
		fmt.Println("interp(before) == interp(after)")
	}
}

