// fir Phase 3 — Optimizer 검증
// 원칙: interp(before) == interp(after), 그리고 코드가 줄어야 함
package main

import (
	"fmt"
	"fir/src/interp"
	"fir/src/ir"
	"fir/src/irgen"
	"fir/src/opt"
)

var optPassed, optFailed int

// ----------------------------------------------------------------
// 헬퍼
// ----------------------------------------------------------------

func countInsts(mod *ir.Module) int {
	n := 0
	for _, fn := range mod.Functions {
		for _, b := range fn.Blocks {
			n += len(b.Insts)
		}
	}
	return n
}

// 최적화 전후 interp 결과 동일, 명령 수 감소/동일 검증
func assertOpt(label string, mod *ir.Module, fnName string,
	args []interp.RVal, expected int64) {
	before, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | before interp: %v\n", label, err)
		optFailed++
		return
	}
	nBefore := countInsts(mod)

	// 최적화 실행
	pm := opt.Standard()
	modOpt := pm.Run(mod)

	after, err := interp.ExecModule(modOpt, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | after interp: %v\n", label, err)
		optFailed++
		return
	}
	nAfter := countInsts(modOpt)

	if before.AsInt() != expected {
		fmt.Printf("[FAIL] %s | before=%d expected=%d\n", label, before.AsInt(), expected)
		optFailed++
		return
	}
	if after.AsInt() != expected {
		fmt.Printf("[FAIL] %s | after=%d expected=%d (semantics broken!)\n",
			label, after.AsInt(), expected)
		optFailed++
		return
	}

	fmt.Printf("[PASS] %s | result=%d insts: %d→%d (-%d)\n",
		label, expected, nBefore, nAfter, nBefore-nAfter)
	optPassed++
}

// FL 소스 경유 최적화 검증
func assertOptFL(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | irgen: %v\n", label, err)
		optFailed++
		return
	}
	assertOpt(label, mod, fnName, args, expected)
}

// ----------------------------------------------------------------
// 테스트: ConstFold
// ----------------------------------------------------------------

func testConstFold() {
	fmt.Println("--- P3.3: Constant Folding ---")

	// CF-1: 양쪽 상수 binop
	{
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBinop("add", "r", ir.I64(),
			ir.ConstInt(3, ir.I64()), ir.ConstInt(4, ir.I64())))
		entry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
		fn := ir.NewFunction("f", nil, ir.I64(), false)
		fn.AddBlock(entry)
		mod := ir.NewModule("cf1"); mod.AddFunction(fn)
		assertOpt("CF-1: 3+4=7", mod, "f", nil, 7)
	}

	// CF-2: 중첩 상수 (3*4 + 2)
	{
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBinop("mul", "a", ir.I64(),
			ir.ConstInt(3, ir.I64()), ir.ConstInt(4, ir.I64())))
		entry.Add(ir.NewBinop("add", "r", ir.I64(),
			ir.Reg("a", ir.I64()), ir.ConstInt(2, ir.I64())))
		entry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
		fn := ir.NewFunction("f", nil, ir.I64(), false)
		fn.AddBlock(entry)
		mod := ir.NewModule("cf2"); mod.AddFunction(fn)
		assertOpt("CF-2: 3*4+2=14", mod, "f", nil, 14)
	}

	// CF-3: identity rule (x + 0 = x)
	{
		params := []ir.Param{{Name: "x", Type: ir.I64()}}
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBinop("add", "r", ir.I64(),
			ir.Reg("x", ir.I64()), ir.ConstInt(0, ir.I64())))
		entry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
		fn := ir.NewFunction("f", params, ir.I64(), false)
		fn.AddBlock(entry)
		mod := ir.NewModule("cf3"); mod.AddFunction(fn)
		assertOpt("CF-3: x+0=x (id)", mod, "f",
			[]interp.RVal{interp.RInt(42)}, 42)
	}

	// CF-4: zero rule (x * 0 = 0)
	{
		params := []ir.Param{{Name: "x", Type: ir.I64()}}
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBinop("mul", "r", ir.I64(),
			ir.Reg("x", ir.I64()), ir.ConstInt(0, ir.I64())))
		entry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
		fn := ir.NewFunction("f", params, ir.I64(), false)
		fn.AddBlock(entry)
		mod := ir.NewModule("cf4"); mod.AddFunction(fn)
		assertOpt("CF-4: x*0=0 (zero)", mod, "f",
			[]interp.RVal{interp.RInt(99)}, 0)
	}

	// CF-5: constant icmp → bool
	{
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewICmp("lt", "c", ir.I64(),
			ir.ConstInt(3, ir.I64()), ir.ConstInt(5, ir.I64())))
		entry.Add(ir.NewRet(ir.Reg("c", ir.Bool())))
		fn := ir.NewFunction("f", nil, ir.I64(), false)
		fn.AddBlock(entry)
		mod := ir.NewModule("cf5"); mod.AddFunction(fn)
		assertOpt("CF-5: icmp 3<5=1", mod, "f", nil, 1)
	}

	// CF-6: constant brcond 제거
	{
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBrCond(ir.ConstBool(true), "yes", "no"))
		yes := ir.NewBlock("yes")
		yes.Add(ir.NewRet(ir.ConstInt(1, ir.I64())))
		no := ir.NewBlock("no")
		no.Add(ir.NewRet(ir.ConstInt(0, ir.I64())))
		fn := ir.NewFunction("f", nil, ir.I64(), false)
		fn.AddBlock(entry); fn.AddBlock(yes); fn.AddBlock(no)
		mod := ir.NewModule("cf6"); mod.AddFunction(fn)
		assertOpt("CF-6: brcond true→br yes", mod, "f", nil, 1)
	}

	// CF-7: xor %x, %x = 0
	{
		params := []ir.Param{{Name: "x", Type: ir.I64()}}
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBinop("xor", "r", ir.I64(),
			ir.Reg("x", ir.I64()), ir.Reg("x", ir.I64())))
		entry.Add(ir.NewRet(ir.Reg("r", ir.I64())))
		fn := ir.NewFunction("f", params, ir.I64(), false)
		fn.AddBlock(entry)
		mod := ir.NewModule("cf7"); mod.AddFunction(fn)
		assertOpt("CF-7: x^x=0", mod, "f",
			[]interp.RVal{interp.RInt(777)}, 0)
	}

	// CF-8: FL 소스 경유 — 상수만 있는 함수
	assertOptFL("CF-8: FL const fn",
		`fn answer() -> i64 { return 6 * 7 }`,
		"answer", nil, 42)

	// CF-9: FL — if(true) → 분기 제거
	assertOptFL("CF-9: FL if(1>0) folded",
		`fn f() -> i64 {
			let x: i64 = 5
			let y: i64 = 3
			return x + y
		}`,
		"f", nil, 8)

	// CF-10: trunc 상수 폴딩
	{
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewCast("trunc", "r", ir.I64(),
			ir.ConstInt(300, ir.I64()), ir.I8()))
		entry.Add(ir.NewRet(ir.Reg("r", ir.I8())))
		fn := ir.NewFunction("f", nil, ir.I8(), false)
		fn.AddBlock(entry)
		mod := ir.NewModule("cf10"); mod.AddFunction(fn)
		assertOpt("CF-10: trunc 300→i8=44", mod, "f", nil, 44)
	}
}

// ----------------------------------------------------------------
// 테스트: DCE
// ----------------------------------------------------------------

func testDCE() {
	fmt.Println("--- P3.2: Dead Code Elimination ---")

	// DCE-1: 사용되지 않는 binop 제거
	{
		params := []ir.Param{{Name: "x", Type: ir.I64()}}
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBinop("mul", "dead", ir.I64(),
			ir.Reg("x", ir.I64()), ir.ConstInt(99, ir.I64())))
		entry.Add(ir.NewRet(ir.Reg("x", ir.I64())))
		fn := ir.NewFunction("f", params, ir.I64(), false)
		fn.AddBlock(entry)
		mod := ir.NewModule("dce1"); mod.AddFunction(fn)
		assertOpt("DCE-1: dead mul removed", mod, "f",
			[]interp.RVal{interp.RInt(42)}, 42)
	}

	// DCE-2: 연쇄 dead code
	{
		params := []ir.Param{{Name: "x", Type: ir.I64()}}
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBinop("add", "a", ir.I64(),
			ir.Reg("x", ir.I64()), ir.ConstInt(1, ir.I64())))
		entry.Add(ir.NewBinop("mul", "b", ir.I64(),
			ir.Reg("a", ir.I64()), ir.ConstInt(2, ir.I64())))
		// b는 사용 안 함
		entry.Add(ir.NewRet(ir.Reg("x", ir.I64())))
		fn := ir.NewFunction("f", params, ir.I64(), false)
		fn.AddBlock(entry)
		mod := ir.NewModule("dce2"); mod.AddFunction(fn)
		assertOpt("DCE-2: chain dead removed", mod, "f",
			[]interp.RVal{interp.RInt(7)}, 7)
	}

	// DCE-3: FL — 쓰지 않는 let 변수
	assertOptFL("DCE-3: FL unused let",
		`fn f(x: i64) -> i64 {
			let unused: i64 = x * 999
			return x + 1
		}`,
		"f", []interp.RVal{interp.RInt(41)}, 42)
}

// ----------------------------------------------------------------
// 테스트: ConstFold + DCE 연계
// ----------------------------------------------------------------

func testCombined() {
	fmt.Println("--- P3.3+P3.2: Combined ---")

	// COMB-1: FL — 상수 표현식 폴딩 후 dead code 제거
	assertOptFL("COMB-1: FL const+dce",
		`fn f() -> i64 {
			let a: i64 = 3 * 4
			let b: i64 = 10 - 10
			return a + 2
		}`,
		"f", nil, 14)

	// COMB-2: 상수 조건 분기 → 한쪽 블록만 살아남
	assertOptFL("COMB-2: while sum(5)",
		`fn sum(n: i64) -> i64 {
			let s: i64 = 0
			let i: i64 = 0
			while i < n {
				s = s + i
				i = i + 1
			}
			return s
		}`,
		"sum", []interp.RVal{interp.RInt(5)}, 10)

	// COMB-3: factorial 최적화 후 의미 보존
	assertOptFL("COMB-3: factorial(6)=720",
		`fn factorial(n: i64) -> i64 {
			if n <= 1 { return 1 }
			return n * factorial(n - 1)
		}`,
		"factorial", []interp.RVal{interp.RInt(6)}, 720)
}

// ----------------------------------------------------------------
// 테스트: Dead Block Elimination
// ----------------------------------------------------------------

func countBlocks(mod *ir.Module) int {
	n := 0
	for _, fn := range mod.Functions {
		n += len(fn.Blocks)
	}
	return n
}

// 최적화 전후 interp 결과 동일 + 블록 수 감소 검증
func assertDeadBlock(label string, mod *ir.Module, fnName string,
	args []interp.RVal, expected int64, wantBlockReduced bool) {
	before, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | before interp: %v\n", label, err)
		optFailed++
		return
	}
	bBefore := countBlocks(mod)

	pm := opt.Standard()
	modOpt := pm.Run(mod)

	after, err := interp.ExecModule(modOpt, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | after interp: %v\n", label, err)
		optFailed++
		return
	}
	bAfter := countBlocks(modOpt)

	if before.AsInt() != expected || after.AsInt() != expected {
		fmt.Printf("[FAIL] %s | before=%d after=%d expected=%d\n",
			label, before.AsInt(), after.AsInt(), expected)
		optFailed++
		return
	}
	if wantBlockReduced && bAfter >= bBefore {
		fmt.Printf("[FAIL] %s | blocks not reduced: %d→%d\n", label, bBefore, bAfter)
		optFailed++
		return
	}
	fmt.Printf("[PASS] %s | result=%d blocks: %d→%d (-%d)\n",
		label, expected, bBefore, bAfter, bBefore-bAfter)
	optPassed++
}

func testDeadBlock() {
	fmt.Println("--- DeadBlock: Dead Block Elimination ---")

	// DB-1: brcond true → br, dead 블록 제거
	{
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBrCond(ir.ConstBool(true), "yes", "no"))
		yes := ir.NewBlock("yes")
		yes.Add(ir.NewRet(ir.ConstInt(1, ir.I64())))
		no := ir.NewBlock("no")
		no.Add(ir.NewRet(ir.ConstInt(0, ir.I64())))
		fn := ir.NewFunction("f", nil, ir.I64(), false)
		fn.AddBlock(entry); fn.AddBlock(yes); fn.AddBlock(no)
		mod := ir.NewModule("db1"); mod.AddFunction(fn)
		assertDeadBlock("DB-1: brcond true → no block removed", mod, "f", nil, 1, true)
	}

	// DB-2: brcond false → br, dead 블록 제거
	{
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBrCond(ir.ConstBool(false), "yes", "no"))
		yes := ir.NewBlock("yes")
		yes.Add(ir.NewRet(ir.ConstInt(1, ir.I64())))
		no := ir.NewBlock("no")
		no.Add(ir.NewRet(ir.ConstInt(0, ir.I64())))
		fn := ir.NewFunction("f", nil, ir.I64(), false)
		fn.AddBlock(entry); fn.AddBlock(yes); fn.AddBlock(no)
		mod := ir.NewModule("db2"); mod.AddFunction(fn)
		assertDeadBlock("DB-2: brcond false → yes block removed", mod, "f", nil, 0, true)
	}

	// DB-3: 연쇄 dead block (두 단계)
	{
		// entry → brcond(true) → yes(→ end) / no(→ end)
		// no가 제거되면 end의 phi incoming도 정리되어야 함
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewBrCond(ir.ConstBool(true), "yes", "no"))
		yes := ir.NewBlock("yes")
		yes.Add(ir.NewRet(ir.ConstInt(10, ir.I64())))
		no := ir.NewBlock("no")
		no.Add(ir.NewRet(ir.ConstInt(20, ir.I64())))
		fn := ir.NewFunction("f", nil, ir.I64(), false)
		fn.AddBlock(entry); fn.AddBlock(yes); fn.AddBlock(no)
		mod := ir.NewModule("db3"); mod.AddFunction(fn)
		assertDeadBlock("DB-3: chain dead block (true→10)", mod, "f", nil, 10, true)
	}

	// DB-4: FL 소스 경유 — if(1>0) → else 블록 제거
	assertOptFL("DB-4: FL if(true) dead else removed",
		`fn f() -> i64 {
			if 1 > 0 { return 99 }
			return 0
		}`,
		"f", nil, 99)

	// DB-5: 도달 가능 블록은 보존
	{
		params := []ir.Param{{Name: "x", Type: ir.I64()}}
		entry := ir.NewBlock("entry")
		entry.Add(ir.NewICmp("gt", "c", ir.I64(),
			ir.Reg("x", ir.I64()), ir.ConstInt(0, ir.I64())))
		entry.Add(ir.NewBrCond(ir.Reg("c", ir.Bool()), "pos", "neg"))
		pos := ir.NewBlock("pos")
		pos.Add(ir.NewRet(ir.ConstInt(1, ir.I64())))
		neg := ir.NewBlock("neg")
		neg.Add(ir.NewRet(ir.ConstInt(-1, ir.I64())))
		fn := ir.NewFunction("f", params, ir.I64(), false)
		fn.AddBlock(entry); fn.AddBlock(pos); fn.AddBlock(neg)
		mod := ir.NewModule("db5"); mod.AddFunction(fn)
		// 동적 brcond → 블록 수 유지
		assertDeadBlock("DB-5: dynamic brcond, both blocks kept (pos)", mod, "f",
			[]interp.RVal{interp.RInt(5)}, 1, false)
	}
}

// ----------------------------------------------------------------
// 진입점
// ----------------------------------------------------------------

// ----------------------------------------------------------------
// 테스트: mem2reg
// ----------------------------------------------------------------

// Full 파이프라인으로 alloca 제거 검증
func assertMem2Reg(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | irgen: %v\n", label, err)
		optFailed++
		return
	}

	// before: interp 확인
	before, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | before interp: %v\n", label, err)
		optFailed++
		return
	}
	if before.AsInt() != expected {
		fmt.Printf("[FAIL] %s | before=%d expected=%d\n", label, before.AsInt(), expected)
		optFailed++
		return
	}

	nAllocaBefore := countAllocas(mod)

	// Full 파이프라인 실행
	modOpt := opt.Full().Run(mod)

	// after: interp 확인 (의미 보존)
	after, err := interp.ExecModule(modOpt, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | after interp: %v\n", label, err)
		optFailed++
		return
	}
	if after.AsInt() != expected {
		fmt.Printf("[FAIL] %s | after=%d expected=%d (semantics broken!)\n",
			label, after.AsInt(), expected)
		optFailed++
		return
	}

	nAllocaAfter := countAllocas(modOpt)
	fmt.Printf("[PASS] %s | result=%d alloca: %d→%d (-%d)\n",
		label, expected, nAllocaBefore, nAllocaAfter, nAllocaBefore-nAllocaAfter)
	optPassed++
}

func countAllocas(mod *ir.Module) int {
	n := 0
	for _, fn := range mod.Functions {
		for _, b := range fn.Blocks {
			for _, inst := range b.Insts {
				if inst.Kind == ir.InstAlloca {
					n++
				}
			}
		}
	}
	return n
}

func testMem2Reg() {
	fmt.Println("--- P3.1: mem2reg (alloca → phi) ---")

	// M2R-1: 단순 let 변수 (단일 블록)
	assertMem2Reg("M2R-1: simple let x=42",
		`fn f() -> i64 {
			let x: i64 = 42
			return x
		}`,
		"f", nil, 42)

	// M2R-2: 파라미터 승격
	assertMem2Reg("M2R-2: param passthrough",
		`fn f(x: i64) -> i64 {
			return x + 1
		}`,
		"f", []interp.RVal{interp.RInt(41)}, 42)

	// M2R-3: if/else 분기 (phi 노드 필요)
	assertMem2Reg("M2R-3: if/else → phi",
		`fn f(x: i64) -> i64 {
			let r: i64 = 0
			if x > 0 {
				r = 1
			} else {
				r = -1
			}
			return r
		}`,
		"f", []interp.RVal{interp.RInt(5)}, 1)

	assertMem2Reg("M2R-3b: if/else → phi (neg)",
		`fn f(x: i64) -> i64 {
			let r: i64 = 0
			if x > 0 {
				r = 1
			} else {
				r = -1
			}
			return r
		}`,
		"f", []interp.RVal{interp.RInt(-3)}, -1)

	// M2R-4: while 루프 (루프 phi)
	assertMem2Reg("M2R-4: while sum(5)=10",
		`fn sum(n: i64) -> i64 {
			let s: i64 = 0
			let i: i64 = 0
			while i < n {
				s = s + i
				i = i + 1
			}
			return s
		}`,
		"sum", []interp.RVal{interp.RInt(5)}, 10)

	// M2R-5: 복수 변수
	assertMem2Reg("M2R-5: multi var",
		`fn f(a: i64, b: i64) -> i64 {
			let x: i64 = a + b
			let y: i64 = x * 2
			return y
		}`,
		"f", []interp.RVal{interp.RInt(3), interp.RInt(4)}, 14)

	// M2R-6: factorial (재귀 + 파라미터 승격)
	assertMem2Reg("M2R-6: factorial(6)=720",
		`fn factorial(n: i64) -> i64 {
			if n <= 1 { return 1 }
			return n * factorial(n - 1)
		}`,
		"factorial", []interp.RVal{interp.RInt(6)}, 720)
}

func runOptTests() {
	fmt.Println()
	fmt.Println("=== Optimizer Tests (Phase 3) ===")

	testConstFold()
	testDCE()
	testDeadBlock()
	testMem2Reg()
	testCombined()

	fmt.Println()
	fmt.Printf("Optimizer Results: %d/%d PASS\n", optPassed, optPassed+optFailed)
	if optFailed == 0 {
		fmt.Println()
		fmt.Println("OPTIMIZER VERIFIED")
		fmt.Println("interp(before) == interp(after)")
	}
}

