type CompiledModule struct {
	Code     []byte         // 전체 코드 섹션
	FuncOff  map[string]int // 함수명 → 코드 내 오프셋
	FuncSize map[string]int
}

func CompileModule(mod *ir.Module) (*CompiledModule, error) {
	cm := &CompiledModule{
		FuncOff:  make(map[string]int),
		FuncSize: make(map[string]int),
	}

	// 단일 공유 Asm — 함수 간 레이블을 동일 공간에서 해소
	sharedAsm := NewAsm()

	// 함수 레이블 맵 (fn name → entry label)
	// 블록 레이블 = fnName + "__" + blockLabel
	// 함수 진입점 = fnName + "__entry"
	funcLabels := make(map[string]string)
	for _, fn := range mod.Functions {
		funcLabels[fn.Name] = fn.Name + "__entry"
	}

	// 각 함수 컴파일 → sharedAsm에 직접 emit
	for _, fn := range mod.Functions {
		off := sharedAsm.Len()
		cm.FuncOff[fn.Name] = off

		if err := compileFuncInto(sharedAsm, fn, funcLabels); err != nil {
			return nil, fmt.Errorf("compile %s: %w", fn.Name, err)
		}

		cm.FuncSize[fn.Name] = sharedAsm.Len() - off
	}

	// 모든 함수 컴파일 완료 후 전체 fixup 해소
	if err := sharedAsm.ResolveFixups(); err != nil {
		return nil, err
	}

	cm.Code = sharedAsm.Bytes()
	return cm, nil
}

// compileFuncInto: fn을 sharedAsm에 컴파일
func compileFuncInto(a *Asm, fn *ir.Function, funcLabels map[string]string) error {
	fc := &FuncCompiler{
		fn:      fn,
		asm:     a,
		slots:   make(map[string]int32),
		nextOff: 0,
		funcMap: funcLabels,
	}

	// 1패스: 슬롯 미리 등록
	for _, b := range fn.Blocks {
		for _, inst := range b.Insts {
			if inst.Result != "" { fc.slot(inst.Result) }
		}
	}
	for _, p := range fn.Params { fc.slot(p.Name) }
	fc.slot("__tmp_lhs__")

	frameSize := fc.stackSize()

	// 함수 진입 레이블 — prologue 이전에 등록
	a.MarkLabel(fn.Name + "__entry")

	// prologue
	a.Push(RBP)
	a.MovRR(RBP, RSP)
	a.SubSP(frameSize)

	// 파라미터 → 스택 슬롯
	for i, p := range fn.Params {
		if i < len(argRegs) {
			a.StoreStack(fc.slot(p.Name), argRegs[i])
		}
	}

	// 블록 컴파일
	for _, b := range fn.Blocks {
		// entry 블록은 이미 레이블 등록됨 (prologue 전). 나머지만 등록.
		if b.Label != "entry" {
			a.MarkLabel(fn.Name + "__" + b.Label)
		}
		for _, inst := range b.Insts {
			if err := fc.compileInst(inst); err != nil { return err }
		}
	}

	// 함수별 fixup은 ResolveFixups를 호출하지 않음
	// → 모듈 전체 컴파일 후 CompileModule에서 일괄 해소
	return nil
}

