// fir Phase 3.6 — RegAlloc 검증
// 원칙: interp(optimized) == native(regalloc) 결과 동일
package main

import (
	"fmt"
	"fir/src/codegen"
	"fir/src/interp"
	"fir/src/irgen"
	"fir/src/opt"
)

var raPassed, raFailed int

// ----------------------------------------------------------------
// 헬퍼
// ----------------------------------------------------------------

func assertRegAlloc(label, src, fnName string, args []interp.RVal, expected int64) {
	mod, err := irgen.Compile(src)
	if err != nil {
		fmt.Printf("[FAIL] %s | irgen: %v\n", label, err)
		raFailed++
		return
	}

	// interp (최적화 전)
	interpBefore, err := interp.ExecModule(mod, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp: %v\n", label, err)
		raFailed++
		return
	}
	if interpBefore.AsInt() != expected {
		fmt.Printf("[FAIL] %s | interp=%d expected=%d\n", label, interpBefore.AsInt(), expected)
		raFailed++
		return
	}

	// opt.Full() 적용
	modOpt := opt.Full().Run(mod)

	// interp (최적화 후) — 의미 보존 확인
	interpAfter, err := interp.ExecModule(modOpt, fnName, args)
	if err != nil {
		fmt.Printf("[FAIL] %s | interp(opt): %v\n", label, err)
		raFailed++
		return
	}
	if interpAfter.AsInt() != expected {
		fmt.Printf("[FAIL] %s | interp(opt)=%d expected=%d (opt broke semantics!)\n",
			label, interpAfter.AsInt(), expected)
		raFailed++
		return
	}

	// RegAlloc: 함수별 계산
	raMap := make(map[string]*opt.RegAllocResult)
	for _, fn := range modOpt.Functions {
		raMap[fn.Name] = opt.RegAllocFunc(fn)
	}

	// RegAlloc 통계 출력
	ra := raMap[fnName]
	physCount, spillCount := 0, 0
	if ra != nil {
		for _, idx := range ra.PhysReg {
			if idx >= 0 {
				physCount++
			} else {
				spillCount++
			}
		}
	}

	// native 실행 (RegAlloc 적용 코드젠)
	cm, err := codegen.CompileModuleWithRA(modOpt, raMap)
	if err != nil {
		fmt.Printf("[FAIL] %s | codegen(ra): %v\n", label, err)
		raFailed++
		return
	}

	off, ok := cm.FuncOff[fnName]
	if !ok {
		fmt.Printf("[FAIL] %s | entry not found\n", label)
		raFailed++
		return
	}

	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	exitCode, err := execElf(elfBytes)
	if err != nil {
		fmt.Printf("[SKIP] %s | native: %v\n", label, err)
		return
	}

	if exitCode == expected {
		fmt.Printf("[PASS] %s | result=%d regs=%d spills=%d\n",
			label, exitCode, physCount, spillCount)
		raPassed++
	} else {
		fmt.Printf("[FAIL] %s | native=%d expected=%d (interp=%d)\n",
			label, exitCode, expected, interpAfter.AsInt())
		raFailed++
	}
}

// ----------------------------------------------------------------
// 테스트
// ----------------------------------------------------------------

func testRegAlloc() {
	fmt.Println("--- P3.6: Linear Scan Register Allocation ---")

	// RA-1: 단순 연산 (레지스터 할당 기본)
	assertRegAlloc("RA-1: simple add",
		`fn f(x: i64) -> i64 {
			return x + 1
		}`,
		"f", []interp.RVal{interp.RInt(41)}, 42)

	// RA-2: 다변수 (여러 SSA 값 동시 레지스터)
	assertRegAlloc("RA-2: multi var",
		`fn f(a: i64, b: i64) -> i64 {
			let x: i64 = a + b
			let y: i64 = x * 2
			return y
		}`,
		"f", []interp.RVal{interp.RInt(3), interp.RInt(4)}, 14)

	// RA-3: if/else (phi 후 레지스터)
	assertRegAlloc("RA-3: if/else",
		`fn f(x: i64) -> i64 {
			let r: i64 = 0
			if x > 0 {
				r = 1
			} else {
				r = -1
			}
			return r
		}`,
		"f", []interp.RVal{interp.RInt(5)}, 1)

	assertRegAlloc("RA-3b: if/else (neg path)",
		`fn f(x: i64) -> i64 {
			let r: i64 = 0
			if x > 0 {
				r = 1
			} else {
				r = -1
			}
			return r
		}`,
		"f", []interp.RVal{interp.RInt(-3)}, 255) // exit code: (-1 & 0xFF) = 255

	// RA-4: while 루프 (루프 변수 레지스터 유지)
	assertRegAlloc("RA-4: while sum(5)=10",
		`fn sum(n: i64) -> i64 {
			let s: i64 = 0
			let i: i64 = 0
			while i < n {
				s = s + i
				i = i + 1
			}
			return s
		}`,
		"sum", []interp.RVal{interp.RInt(5)}, 10)

	// RA-5: 재귀 함수
	assertRegAlloc("RA-5: factorial(6)=720→208",
		`fn factorial(n: i64) -> i64 {
			if n <= 1 { return 1 }
			return n * factorial(n - 1)
		}`,
		"factorial", []interp.RVal{interp.RInt(6)}, 720%256) // exit code mod 256
}

func runRATests() {
	fmt.Println()
	fmt.Println("=== RegAlloc Tests (Phase 3.6) ===")

	testRegAlloc()

	fmt.Println()
	fmt.Printf("RegAlloc Results: %d/%d PASS\n", raPassed, raPassed+raFailed)
	if raFailed == 0 {
		fmt.Println()
		fmt.Println("REGALLOC VERIFIED")
		fmt.Println("interp == native (with register allocation)")
	}
}

